('XiangZi_10_14', '玄黄笔法歌', '衣礼', '礼字旁边折，必定见生财。疋字如逢见，须从人正来。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·衣礼'),
('XiangZi_10_15', '玄黄笔法歌', '月骨', '骨傍人有祸，囚狱一重来。门内生荆棘，施设不和谐。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·月骨'),
('XiangZi_10_16', '玄黄笔法歌', '身自', '自家身傍限，分明身不全。有谋难得遂，即日是多煎。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·身自'),
('XiangZi_10_17', '玄黄笔法歌', '反定', '定绕自来看，身必有所动。吉凶意如何，相里临时用。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·反定'),
('XiangZi_10_18', '玄黄笔法歌', '山山', '山下灾祥字，占家宜用官。更推从西用，凶吉数中安。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·山山'),
('XiangZi_10_19', '玄黄笔法歌', '人欠', '欠字从西体，须知望用难。吹嘘无首尾，不用滞眉看。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·人欠'),
('XiangZi_10_20', '玄黄笔法歌', '禾禾', '禾边刀是利，春季则为殃。夏日宜更改，人中好举扬。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·禾禾'),
('XiangZi_10_21', '玄黄笔法歌', '耳耳', '耳畔虽有纪，轻则是虚声。旺事宜重用，取谋合有成。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·耳耳'),
('XiangZi_10_22', '玄黄笔法歌', '彐', '彐字作横山，取之衣禄渐明矣。又作日间防破。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·彐'),
('XiangZi_10_23', '玄黄笔法歌', '申', '申字作破田煞，常人不辨破田之说，用事重成之义也。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·申'),
('XiangZi_10_24', '玄黄笔法歌', '田', '田字藏器待时，头足有所争，争而有所私，忌田产不宁。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·田'),
('XiangZi_10_25', '玄黄笔法歌', '黄', '黄字作廿一后，方得萌芽；又作廿一用，可喜也。又云：上有一堆草，中有一条梁，撑杀由八郎。', '卷之四·玄黄笔法歌', '相字·玄黄笔法歌·黄'),
('XiangZi_11_01', '辨别五行歌', '其1', '一：横画连勾作土称，一挑一捺俱为金。撇长撇短皆为火，横直交加土最深。有直不斜方是木，学者方明正五行。', '卷之四·辨别五行歌', '相字·辨别五行歌·其1'),
('XiangZi_11_02', '辨别五行歌', '其2', '二：一点悬空土迸尘，三直相连化水名。孤直无依为冷木，腹中横短作囊金。点边得撇为炎火，五行变化在其中。', '卷之四·辨别五行歌', '相字·辨别五行歌·其2'),
('XiangZi_11_03', '辨别五行歌', '其3', '三：三横两短若无钩，乃为湿木水中流。两点如挑金在水，八字相须火可求。空云独作寒金断，好把心勾比木舟。', '卷之四·辨别五行歌', '相字·辨别五行歌·其3'),
('XiangZi_11_04', '辨别五行歌', '其4', '四：无勾之画土稍寒，直非端正木休参。围中横满无源水，口小金方莫错谈。四匡无风全五事，用心辨别莫疑难。', '卷之四·辨别五行歌', '相字·辨别五行歌·其4'),
('XiangZi_11_05', '辨别五行歌', '其5', '五：穿心撇捺火陶金，走之平稳水溶溶。直中一捺金伤木，踢起无尖不是金。数点笔连休作火，奇奇偶偶水源清。', '卷之四·辨别五行歌', '相字·辨别五行歌·其5'),
('XiangZi_11_06', '辨别五行歌', '其6', '六：无直无钩独有横，水因土化复何云。点挑撇捺同相聚，其总将来化土音。四点不连真化火，孤行一笔五行同。', '卷之四·辨别五行歌', '相字·辨别五行歌·其6'),
('XiangZi_12_01', '辨别六神歌', '总诀', '蚕头燕额是青龙，尖短交加朱雀神。弯弓斜月勾陈象，腾蛇长曲势如行。尾尖口阔为白虎，体态方尖玄武行。此即六神真妙诀，断事详占要认真。', '卷之四·辨别六神歌', '相字·总诀'),
('XiangZi_13_01', '八卦辨', '总诀', '口形为兑捺为乾，三画无伤乾亦然。三点同来方是坎，撇如双见作离占。土山居上名为艮，居下为坤不必言。蛇形孤撇皆从巽，云首龙头震占先。详明八卦知凶吉，学者参求理自全。', '卷之五·八卦辨', '相字·总诀'),
('XiangZi_14_01', '五行歌并式', '总诀', '木瘦金方水主肥，土形敦厚背如龟。上尖下阔名为火，字像人形一样推。', '卷之四·五行歌并式', '相字·总诀'),
('XiangZi_15_01', '相字短诀', '相字心易', '凡写两字，止看一字。盖字多必乱，若谋事之类，亦必移时方可再看。', '卷之四·字画指迷', '相字·相字短诀·相字心易'),
('XiangZi_15_02', '相字短诀', '辨字式', '富人字多稳重无枯淡；贵人字多清奇、长画肥大；贫人之字多枯淡无精神；贱人字多散乱带空亡；百工字多挑跃；商贾字多远迩；男子字多开阔；妇人字多逼侧。余皆浓淡肥瘦、斜正分明之类断之。', '卷之四·字画指迷', '相字·相字短诀·辨字式'),
('XiangZi_15_03', '相字短诀', '当添亦添', '如官员写「尹」字，乃君字首断，其人必见上位，定不禄而还，以君无口故也；如书「君」字，乃郡旁，其人当得郡守。', '卷之四·字画指迷', '相字·相字短诀·当添亦添'),
('XiangZi_15_04', '相字短诀', '当减亦减', '如「树」字，中有「吉」字，写得好者，则减去两边，只是言吉。', '卷之四·字画指迷', '相字·相字短诀·当减亦减'),
('XiangZi_15_05', '相字短诀', '以卦而断', '如「震」字，春则得时，冬则无气，皆以其卦言之。', '卷之四·字画指迷', '相字·相字短诀·以卦而断'),
('XiangZi_15_06', '相字短诀', '以时而言', '如草木字，春夏则生旺有财，秋冬则衰替多灾。风云气候之候亦然。', '卷之四·字画指迷', '相字·相字短诀·以时而言'),
('XiangZi_15_07', '相字短诀', '以禽兽而断', '如「牛」字，则为人劳苦。春夏劳苦，秋冬安逸。', '卷之四·字画指迷', '相字·相字短诀·以禽兽而断'),
('XiangZi_15_08', '相字短诀', '取类而言', '如「楼」字，笔画多不可分解，以楼取义，乃重屋也；重屋拆开，乃千里尸至，问字人必有人死在外、尸至之事。', '卷之四·字画指迷', '相字·相字短诀·取类而言'),
('XiangZi_15_09', '相字短诀', '偏旁侵客', '如宀乃家字头，若笔画破断，乃是破家宅，必退；如写作「山」字形，必兴门户；如「山」有缺笔，乃悬针之山，必大凶也。', '卷之四·字画指迷', '相字·相字短诀·偏旁侵客'),
('XiangZi_15_10', '相字短诀', '有所喜', '如问财，见金宝偏旁及禾斗之类，决好。', '卷之四·字画指迷', '相字·相字短诀·有所喜'),
('XiangZi_15_11', '相字短诀', '有所忌', '如问病，见土木；及问讼见「血」「井」字，皆凶。', '卷之四·字画指迷', '相字·相字短诀·有所忌'),
('XiangZi_15_12', '相字短诀', '有所闻', '如问病，忌闻悲泣声；占财不宜破碎声。', '卷之四·字画指迷', '相字·相字短诀·有所闻'),
('XiangZi_15_13', '相字短诀', '有所见', '如「立」字见雨下或水声，则成「泣」字；又如「言」字见「犬」成「獄」字，问病讼皆忌之。', '卷之四·字画指迷', '相字·相字短诀·有所见'),
('XiangZi_15_14', '相字短诀', '视势', '每遇人写来，必别是何字：如「天」字乃「夫」字及「失」字基址——女人写妨夫，男子写有失。', '卷之四·字画指迷', '相字·相字短诀·视势'),
('XiangZi_15_15', '相字短诀', '象人', '凡字必别是何人写，亦象人而言：如「天」字，秀才问科第则来年有望，官员求官宜勉力，庶人占病未安，讼者未了。', '卷之四·字画指迷', '相字·相字短诀·象人'),
('XiangZi_16_01', '分类断法', '问婚姻', '凡字写得相粘者，可成。又字画直落成双者，可成。字中间阔而不粘，及直横成双者，偏旁长短者，不成。凡写字得脚匀齐者，皆就字。四齐者，尤吉字。上短下长者，日久方成字。乾上有破，父不从。坤宫破，母不从。左边长者，男家顺，女家不肯。右边长者，女家顺，男家未然。', '卷之四·字画指迷', '相字·分类断法·问婚姻'),
('XiangZi_16_02', '分类断法', '官事', '或见文字或字脚，一「丿」一「乀」破碎，断有杖责。或见「牛」字，有牢狱之忧，主人大失。或「木」笔开口者，亦有杖责。字画散乱者，易了。或有「丿」「乀」长者耸者，亦有杖刑。或见杖竹之类，亦有打兆。火命人写「水」字来问，必有官灾。或字有草头者，说草头姓，得力之类。', '卷之四·字画指迷', '相字·分类断法·官事'),
('XiangZi_16_03', '分类断法', '疾病', '金笔多，心肺痰，脏腑疾。西方金神为衬。木笔多，心气疾，手足灾。木神林坛为祟。水笔多，泻痢吐呕之症。水鬼为凶。火笔潮热，伤寒时行，火鬼为怪。又云四肢疼，时气疾病。火笔多者，病不死。土笔多，脾胃兼疮疾，客亡，伏尸鬼，疼痛之疾。土笔多者，病死字，凡有丧字、虎字头，或两口字者，皆难救。', '卷之四·字画指迷', '相字·分类断法·疾病'),
('XiangZi_16_04', '分类断法', '六甲', '字凡有「喜」字、「吉」字体者，皆吉。字凡带白虎，必难产，子必死。写得粘者，易产。字画纤断者，主有惊险。字有腾蛇笔者，主虚惊。字画直落成双者，阴喜；成单者，男喜。', '卷之四·字画指迷', '相字·分类断法·六甲'),
('XiangZi_16_05', '分类断法', '求谋', '凡字写得中间阔者，所谋无成。谋字写得相粘者，二十四五前成，盖有隔字体故也。求字来问者，木命人吉，土人不利。', '卷之四·字画指迷', '相字·分类断法·求谋'),
('XiangZi_16_06', '分类断法', '行人远信', '如「行」字写得脚短、一般齐者，人便至。字脚或不齐，行人皆不至。字画直落点多者，其人必陷身。字画少者，人便至。乃详字体格范。', '卷之四·字画指迷', '相字·分类断法·行人远信'),
('XiangZi_16_07', '分类断法', '官贵', '凡字有二数，一点当先者，无阻事济。所写之字，相粘伶俐者，贵人顺。点多者，事不成。', '卷之四·字画指迷', '相字·分类断法·官贵'),
('XiangZi_16_08', '分类断法', '失物', '凡字有失字体，及字中皆难觅，朱雀动，有口舌，日久难寻。金笔多，艮上有破五金之物，宜速寻。土笔多，坎上有破碎之物，在北方古井，或窑边及坑坎之所，瓦器覆藏，五日见。坤上有一钩者，乃奴婢偷去，不可取得。兑上不足，乃妻妾为脚带，金人将去。离上一画不完者，乃南方火命人将去，见官方失物仍在。', '卷之四·字画指迷', '相字·分类断法·失物'),
('XiangZi_16_09', '分类断法', '问寿', '字画写得长而瘦者，寿耐久；如肥壮者，耐劳苦；短促者，无寿。', '卷之四·字画指迷', '相字·分类断法·问寿'),
('XiangZi_16_10', '分类断法', '功名', '字有贵人头者，有功名。字金笔多而端正，及木笔轻而长者，皆贵。', '卷之四·字画指迷', '相字·分类断法·功名'),
('XiangZi_16_11', '分类断法', '行人', '「人」字潦倒，未动。写得「人」字起者，已动。人以「来」字问者，未至。「行」字问者，且待。凡字中有「言」字者，有信至，人未至也。', '卷之四·字画指迷', '相字·分类断法·行人'),
('XiangZi_16_12', '分类断法', '反体', '「喜」字来问者，未可言喜，有舌字脚也。有以「庆」字来问者，未可言庆，有忧字脚也。「星」字来问者，日在上，星辰不见，问病必凶。大凡文人，不可写武字，武人不可写文字。阴人不可写阳字，阳人不可写阴字。皆反常故也。', '卷之四·字画指迷', '相字·分类断法·反体'),
('XiangZi_16_13', '分类断法', '时辰断', '看字先须看时辰，时辰克应不相亲。时辰若遇生其用，作事何忧不趁心。（此字中笔一要用也。）', '卷之四·字画指迷', '相字·分类断法·时辰断'),
('XiangZi_17_01', '字例', '人', '正人作贵相，睡人作病疾，立人旁托人，双人旁动人，其人逆多顺少。从作两人相从，众作群党生事。坐人作阻隔，更作闲人。', '卷之四·字画指迷', '相字·字例·人'),
('XiangZi_17_02', '字例', '心', '三点连珠，一钩新月，皆清奇之象。或竖心性情，作小人之状。近身作十字，作穿心六害，取凡百孤独。', '卷之四·字画指迷', '相字·字例·心'),
('XiangZi_17_03', '字例', '寸', '亦心也。一寸乃十分，为人有十分之望，谋望有分付也，又作一十取之。', '卷之四·字画指迷', '相字·字例·寸'),
('XiangZi_17_04', '字例', '辛', '乃六七日内见，立见于求远；作六十一日，或云有宰相成也。', '卷之四·字画指迷', '相字·字例·辛'),
('XiangZi_17_05', '字例', '言', '有谋有信，取之。', '卷之四·字画指迷', '相字·字例·言'),
('XiangZi_17_06', '字例', '草作木', '如草之作木，取之心不定也。', '卷之四·字画指迷', '相字·字例·草作木'),
('XiangZi_18_01', '赋文', '指迷赋', '尝闻相字乃前贤妙术，古今秘文，为后学之成规，辨吉凶之易见。相人不如相字，相字即相其人。变化如神，精微入圣。自古结绳为政，如今花押成数。言，心声也；字，心画也。心形如笔，笔画一成，分八卦之休囚，定五行之贵贱，决平生之祸福，知目前之吉凶。富贵贫贱，荣枯得失，皆于笔画见之。或将吉为凶，或指凶为吉。先问人之五行，次看人之笔画。相生相旺则吉，相克相泄则凶。如此观之，万无一失。为官则笔满金鱼，致富则笔如宝库。一生孤独，见于字画之欹斜；半世贫穷，乃是笔端之愚浊，非夭即贱。三山削出，皆非显达之人；四大其亡，尽是寂寥之辈。父母俱存兮，乾坤笔肥；母早亡兮，坤笔乃破；父先逝兮，乾笔乃亏。坎是田园并祖宅，稳重加官；艮为男女及兄弟，不宜损折。兑土主妻宫之巧拙，离宫主官禄之荣枯。震为长男，巽为驿马。乾离囚走，壬主竞争。震若勾尖，常招是非。妻定须离，若是圆净，禄官亦要清明。离位昏蒙，乃是剥官之杀。兑宫破碎，宜婚硬命之妻。金命相逢火笔，克陷妻儿。木命亦怕逢金，破财常有。水命不宜土笔，不见男儿。火命若见水笔，定生口舌。土命若见木笔，祖产自消。相生相旺皆吉，相克相刑定凶。举一隅自反，遇五行而相之。略说根源，以示后学。', '卷之四·字画指迷', '相字·指迷赋'),
('XiangZi_18_02', '赋文', '玄黄叙', '龟形未判，此为太古之淳风；鸟迹既分，爰识当时之制字。虽具存于简牍，当深究其源流。成其始者，信不徒然。即其终之，岂无奥义？同田曰富，分贝为贫。两木相并以成林，每水东归是为海。虽纷纷而莫述，即一一而可知。不惟徒羡于简笺，亦可预占乎休咎。春蛇秋蚓，无非归笔下之功。白虎青龙，皆不离毫端之运。今生好癖，博学博文。少年与笔砚相亲，半世与诗书为侣。识鱼鲁之外，穷亥豕之讹，别贤愚之字。昭然于毫端，察祸福之机，了然于心目。鲜而当理，敢学说字之荆公；挟以动人，未逊后来之谢石。得失何劳于龟卜，依违须决于狐疑。岂徒笔下以推尊，亦至梦中而讲究。刀悬梁上，后操刺史之权；松出腹间，果至三公之位。皆前人之已验，非后学之私言。洞察其阴阳，深明乎爻象，则吉凶悔吝可知矣。', '卷之四·字画指迷', '相字·玄黄叙'),
('XiangZi_18_03', '赋文', '玄黄歌', '大抵画乃由心出，以诚剖决要分明。出笔发毫逢定位，笔头若出干无成。墨断定知田土散，纸破须防不正人。犬吠一声防哭泣，鼠来又忌贼来侵。赤硃写字血光动，叶上书来有怨盟。忽见鸡鸣知可喜，人惊梦觉事通灵。马嘶必有行人至，猫过须防不正人。船上不宜书火字，楼头亦忌有官刑。有时戏在炉中写，遇火焚烧忽不宁。破器莫教添砚水，定知财散更伶仃。笔下偶然蝇蟢至，分明六甲动阴人。在左定生男子兆，右至当为添女人。曾见人家轻薄辈，口中含饭问灾迍。直饶目下千般喜，也问刑徒法里寻。花下写来为色欲，女人情意喜相亲。花开花落寻灾福，刻应之时勿目盲。麒麟凤凰为吉兆，猪羊牛马是凡形。此际真搜玄妙理，其中然后有分明。应验止须勤记取，灾祥议论觉风生。', '卷之四·字画指迷', '相字·玄黄歌'),
('XiangZi_18_04', '赋文', '花押赋', '夫押字者，人之心印也。古人以结绳为证，今人以押字为名。大凡穷通之理，皆与阴阳相应。先观五行之衰旺，次察六神之强胜。五行者，立木、卧土、勾金、点火、曲水之象；六神者，青龙、朱雀、腾蛇、玄武、勾陈、白虎之形。上大阔方，火乃发用；坚瘦有兮，木乃生荣。金要方，水要圆，土要肥而木要正。故曰：炎炎火旺，玉堂拜相。洋洋水秀，金阙朝元。木盛兮，仁全义广；金旺兮，性急心刚。土薄而离巢破祖，土厚而福禄绵绵。故曰：土少木多，根根折挫。金少火多，两窟三窝。金斜而定然子少，木曲而中不财丰。盖画长兮，象天居上。土卧厚兮，象地居下。内木停兮，象人在于中央。三才全兮，如身居其大厦。无天有地兮，父早刑。有天无地兮，母先化。有孤木兮，昆弟难倚。天失兮，故基已罢。内实外虚兮，虽才高无成。外实内虚矣，终富贵而显赫。龙蟠古字，必有将相之权。不正偏斜，定是孤穷之客。腾蛇缠体，飘流万里之程。玄武克身，妨妻害子。身之土透天，常违父母之言，而有失兄弟之理。只将正印按五行，仔细推详大小吉凶，搜六神而无不验矣。', '卷之四·字画指迷', '相字·花押赋'),
('XiangZi_18_05', '赋文', '探玄赋', '且夫天字者，乃乾健也，君子体之。地字者，乃坤顺也，庶人宜之。君子书天，得其理也。庶人书地，亦合宜也。夏木春花，此乃敷荣之日；冬梅秋菊，正是开发之时。一有背违，宁无困顿？日字要看停午，月来须问上弦。假如风雨，要逢长旺之时。若是雪霜，莫写炎蒸之候。牡丹芍药，只是虚花。野杏山桃，皆为结实。森森松柏，终为梁栋之材。郁郁蓬蒿，不过园篱之物。书来风竹，判以清虚。写到桑蚕，归于饱暖。锣鸣炮响，可言声势之家。波滚船行，俱作飘流之士。鱼龙上达，犬豕下流。泉石烟霞，自是清贫之士。轩窗台榭，难言暗昧之徒。河海江山，所为广大。涧溪沼沚，作事卑微。灯烛书于夜间，自然耀彩。月星写于日午，定是埋光。椒桂芝兰，岂出常人之口。桑麻禾麦，决非上达之人。黄白绿青红，许以相逢艳冶。宫商角徵羽，言他会遇知音。剑戟戈矛，终归武士。琴书笔砚，乃是文人。问贱与贫，因见自谦之德。书富乃贵，已萌妄想之心。金玉珍珠，不过守财之辈。荣华显达，欲寻及第之方。恩情欢爱，既出笔端。淫荡痴迷，常眠花下。酒浆脍炙，哺啜者必常书之。福寿康宁，老大者多应写此。且如龙蟠虎踞，宁无变化之时？凤翥鸾翔，终有飞腾之日。体如鹭立，孤贫之士无疑。势如鸦飞，饶舌之徒可测。惊蛇失道，只寻入穴之谋。舞鹤离巢，自有冲霄之志。急如鹊跳，是子轻浮。缓似鹅行，斯人稳重。如篁翁郁，休言豁达心怀。似水飘流，未免萧条家道。或若炎炎之火，或如点点之云，一生喜怒无常，终身成败不保。风摇嫩竹，早年卓立难成。雨洗桃花，晚岁羁栖无倚。为人潇洒，乃如千树之汪梅。赋性温柔，何异数株之岩柳。烟萝系树，卓立全倚于他人。霜叶辞柯，飘零不由自己。画似棱棱之枯木，孤苦伶仃。形如泛泛之浮萍，贫穷漂泊。无异巉岩之怪石，险营生。有如耸拔之奇峰，孤高处世。金绳铁索，此非岩谷之幽人。玉树瑶琴，定是邦家之良佐。乱丝缠结，定知公事牵连。利刃交加，即是私家格角。撇如罗带，除遇阴人。捺似拖勾，刑伤及己。勾似锦靴，遭逢官贵。画成横枕，疾病临身。切忌横冲半断，不保荣身。仍嫌直落中枯，难言高寿。剔成新月，出门便见光辉。点作星飞，守旧宁无晦滞。至若挥毫带煞，秉生死之重权。落纸无成，作奔趋之贱役。起腾腾之秀气，主有文章。生凛凛之寒光，宁无声价？半浓半淡，作事多乖。倚东倚西，撑持不暇。字短则沈沦不显，字长则潦倒无成。拾后拈前，所为险阻。忘前顿后，举动趦趄。且如偃仰，遇庶人则成号泣，君子必定飞腾。若是拘挛，逢君子乃是刑囚，庶人必能勤苦。造其理也，即此推之。余向遇异人，曾授玄黄诸篇。今遇异翁授此，赋毕问之曰：“愿得公之名姓。”公不答而去。', '卷之四·字画指迷', '相字·探玄赋'),
('XiangZi_19_01', '六十四卦次第歌', '总诀', '乾坤屯蒙需讼师，比小畜兮履泰否。同人大有谦豫随，蛊临观兮噬嗑贲。剥复无妄大畜颐，大过坎离三十备。咸恒遁兮及大壮，晋与明夷家人睽。蹇解损益夬姤萃，升困井革鼎震继。艮渐归妹丰旅巽，兑涣节兮中孚至。小过既济兼未济，是为下经三十四。', '卷之五·拆字杂编', '相字·六十四卦次第歌·总诀'),
('XiangZi_20_01', '系辞八卦类象歌', '总诀', '乾为君兮首与马，卦属老阳体至刚。坎虽为耳又为豕，艮为手狗男之详。震卦但为龙与足，三卦皆名曰少阳。阳刚终极资阴济，造化因知不易量。坤为臣兮腹与牛，卦属老阴体至柔。离虽为目又为雉，兑为口羊女之流。巽卦但为鸡与股，少阴三卦皆相眸。阴柔终极资阳济，万象搜罗靡不周。', '卷之五·拆字杂编', '相字·系辞八卦类象歌·总诀'),
('XiangZi_21_01', '八反格', '总诀', '问喜何曾喜，问忧未必忧。问乐何曾乐，问愁何曾愁。问死何曾死，（心怀死必活。）问生不曾生。问官官不谐，见财财不成。', '卷之五·拆字杂编', '相字·八反格·总诀'),
('XiangZi_22_01', '四言独步', '总诀', '看字之法，毫不可差。下笔是我，其余是他。子孙父母，官鬼要财。兄弟之类，次序安排。详占一事，先看用神。或强或弱，详断吉凶。用神健旺，事所必宜。用神衰弱，必失其机。字无用神，始推末笔。末笔参差，诸事不立。土头中贝，日月大人。字中有像，便是贵人。贵人在爻，祸事必消。逢险可救，财利必招。左右有人，功名可许。笔法轩昂，上人荐举。求财取债，金忌火多。再逢夏月，本利消磨。五行俱全，人事宜然。用神清楚，妙不可言。相争词讼，字详结尾。两笔分明，胜负立剖。字可平分，讼不成凶。人居圈内，缧绁之中。青龙在数，求谋不误。若无水来，反为无助。玄武自来，水上生财。白虎同至，惹祸招灾。朱雀临头，文书已动。事在公门，不与人共。末勾叠叠，口舌重重。若无救助，毕竟成凶。水冷金寒，亲戚无缘。求谋末遂，作事迁延。五行正旺，财利可求。吉神相助，万事无忧。土内埋金，功名未遂。或者水多，前行可贵。人病在床，木被金伤。六神不动，毕竟无妨。字不出头，蹭蹬乖蹇。五行有救，渐渐可展。字无勾踢，人必平安。凶神乱动，好处成难。末后一笔，一身之原。如无破绽，福寿绵绵。一字联络，骨肉同门。孤悬一点，游子飘蓬。金得炉锤，方成器皿。木无金制，可曰愚农。木从土出，受人培植。水中浮木，波浪成风。落笔小心，作事斟酌。小心太过，为人刻薄。写来粗草，放荡之人。笔端熟溜，书记佣工。字法龙蛇，仕途已往。秀而不俗，文章自广。风流笔法，好逞聪明。写来透古，腹内不空。墨迹滞涩，学问难夸。一笔无停，定是大家。灯前窗下，岁月蹉跎。禾麻菽麦，俱已发科。字无倚靠，不利六亲。字无筋节，事可让人。直仰两足，奔波劳碌。摆尾摇头，必满意足。字问日期，切勿妄许。有丁有日，方可说与。山田草木，咸不宜冬。星辰日月，乃怕朦胧。真正五行，不怕相克。直如用神，求谋易得。笔法未全，作事多难。行人不至，音信杳然。水火多源，木枯无枝。子孙宗派，于此可思。终身事业，我即用神。生我者吉，克我者凶。字只两笔，寿年不一。有撇七三，无撇六一。字如三笔，亦各有数。常为十六，变为念五。无勾为变，有勾为常。依斯立法，仔细推详。字不出头，寿增五岁。当头一点，须减三年。字若无勾，添九可求。字如无直，寿当增十。笔画过半，须知减点。一点三年，岁数可免。耳畔成三，口头除四。明彻斯传，始精相字。妙诀无多，功非一日。仔细详占，万无一失。', '卷之五·拆字杂编', '相字·四言独步·总诀'),
('XiangZi_23_01', '五言作用歌', '总诀', '断事不可泥，变通方是道。细细察根源，始识先贤奥。十人写一字，笔法各不同。一字占十事，情理自然别。六神无变乱，五行有假真。草木看时节，日月察晦明。字中有子孙，子孙必不少。详其盛与衰，便知贤不肖。我克不宜多，多必妻重娶。克我一般多，谐老又可许。青龙值用神，万事皆无阻。若是无水泽，犹为受用苦。白虎值用神，吉事反成凶。官事必受害，疾病重沉沉。用神见朱雀，利于公门中。君子功名吉，小人口舌凶。用神见腾蛇，俱是文书动。功名眼下宜，富贵如春梦。末笔是青龙，万事不成凶。名利皆如意，行人在路中。末笔是朱雀，公事有着落。只恐闺门中，有病无良药。末笔是勾陈，淹留费苦心。行人音信杳，官讼混如尘。末笔是腾蛇，远客即来家。忧疑终不免，官讼苦嗟吁。末笔是白虎，疾病须忧苦。狱讼必牵缠，出往多拦阻。末笔是玄武，盗贼须提防。水土行人利，家中六畜康。末笔看五行，所用看六神。先定吉凶主，然后字中寻。', '卷之五·拆字杂编', '相字·五言作用歌·总诀'),
('XiangZi_24_01', '别理篇', '总诀', '字义浑论，辨别之篇须下学。理研变化，至诚之道可前知。字同事不同，不宜此而宜彼。事同字亦同，倏变吉而变凶。设若中也者，天下之大本。问终身与昆仲，无缘信乎哉。人间之最要，欲要之于朋友。更切再如地天为泰，不遇阳间犹是否。雷火为丰如逢阴极可云临。既虚矣，复反而为盈；既危矣，复还而为安。时盛必衰，天地不逾其数；治极而乱，圣人能预为防。先则看其笔端，然后察其字义。须知字义古怪，学问宜深。笔走龙蛇，峥嵘已过。龙身草草，非正途显达之官。豹字昂昂，是执殳荷戈之职。志无心，定是漂蓬下士。斌不乱，始称文武全才。贝边月下定归期，足畔口头人必促。团团宝盖，多生富贵之家。济济冠裳，定是风云之客。无事生非因北字，有钱不享是亨来。合则婚事难成，力乃功名末妥。以他人问子，男女皆空。书本姓求官，声名远播。书先觅物终须失，写望追人定是亡。马字偏斜，惟恐落人之局。口头阔大，定招闲事之非。青字有人求作主，事可全于月杪。妙字一女欲于归，少亦可出闺门。天字相联，一对良缘先注定。好字相属，百年美眷预生成。丁寸等字，皆才不足之形。占吉之类，皆告不成之象。香开晨昏扬誉远，花占百事一番新。小为本分之人，大是虚名之士。赤子依亲，是每一例可推。大人盖小，因余仿斯可断。贝左一生多享福，空头半世受孤寒。东西南北，欲就其方。左右中前，乃择其地。一人旁立，求名是佐贰之官。一直居中，占身乃正途之士。草木逢春旺，鱼龙得水舒。远字走长人未到，动旁撇短去犹迟。赤子儿曹之类，必利见大人。公祖父师之称，则相逢贵人。孑则立身无寸地，永如立志有衣冠。操为一品之才，饮定大人之食。之非出往必求财，者不呼卢定六畜。奇欲立而不可，用非走而不通。口居中，俨然一颗方印。元落后，前程可定魁名。体用昂昂，功名之客。性情亟亟，荼苦之懦。朔邦还未入朝廊，田里多应在乡党。活泼泼鸢鱼，是飞腾之象；乐滔滔凫雁，为流荡之徒。川上皆圣贤游乐之余，周行是仕宦经由之道。崔巍远人犹在望，平安近事不能成。日小见天长，心粗知胆大。归则归兮归则止，笑如笑兮笑成悲。国字谓何？一口操戈在内。尔来何故？五人合伙同居。火字乃人在水中，一遇羊头为尽美。天字是人居土内，出头一日始逢春。以余字问，必有；以有字问，反无。龙虽在天在田，看笔迹如何布摆。师既容民畜众，察精神始识兴衰。盖载有人，终享皇家福。伞带全备，定是极品官。有撇断为兄弟，无点莫问儿孙。工欲善其事而成艺，何不见其人而亦可？女子并肩生意好，色糸同处病将亡。犯岁君之名，灾殃不小。书童问卜之日，财利可兴。理中变化深长，此乃规矩方圆之至。字理机关悠远，须认精粗为化造之原。', '卷之五·拆字杂编', '相字·别理篇·总诀'),
('XiangZi_25_01', '六言剖断歌', '总诀', '事从天地之义，字乃圣贤之心。静里功夫细阅，其中奥理无穷。圆融莫测其变，来去莫阻其通。笔法先详衰旺，得意始定吉凶。干枯软小为衰，清秀坚昂为旺。详其用神何如，吉凶自然的当。寿夭定于笔墨，取其多寡为占。字如十笔以上，一笔管之六年。字如十笔以下，一笔定其九岁。若在五笔之间，一笔管十六年。笔画过之十五，两笔折作一笔。带草一笔相连，问寿只在目前。笔迹清而拘束，必然游庠在学。笔端浊而放荡，功名必无着落。写来笔法圆活，为人处世谦和。笔底停而又写，为人性慢心多。举笔茫无所措，胸中学问不大。若无写罢复描，行事可为斟酌。富贵出于精神，英雄定于骨格。末后一笔丰隆，到老人称有德。占妻先看其妻，占子先看其子。妻子察其旺衰，据理定其生死。父兄官灾讼狱，父兄要值空亡。如若父兄在数，父兄反见灾殃。一切谋望营求，字要察其虚实。有声无物为虚，有物可见是实。书出眼前之物，察其司重司轻。司重断为有用，司轻大事无成。纳采于归等事，更要加意推详。笔画计其单双，字义察其阴阳。假如子字求子，须防日建逢女。子日如画女字，婚姻百事皆许。一字笔画未全，万事不必开言。字中若有余笔，必须用意详占。先用五行工夫，后穷增减字理。影响毫发无差，谬则难寻千里。学者变化细推，断事无不灵应。', '卷之五·拆字杂编', '相字·六言剖断歌·总诀'),
('XiangZi_26_01', '格物章', '总诀', '物格而后知致，本末须详。事来必先见诚，始终可断。细而长者，以一尺为百年，计寸分而知寿算。方而圆者，以千金比一两，度轻重以定荣枯。落手银圈，放荡终不改。出囊珠石，峥嵘半世尚丰盈。石土不逢时，谓之无用。木金全失气，枉自徒劳。执墨问功名，研求之苦日见不足。端鼎比身命，近贵之体一世非轻。腰下佩觿，所求皆遂。道旁弃核，百事无成。取草问营谋，逢春须茂盛。将银问财帛，有本恐消磨。素纨无诗，当推结识疏。牙签托人，毕竟不顾我。数珠团圆到底，夫妻儿女皆宜。木鱼振作不常，父母兄弟难合。力下行人来得快，笔占远处有施为。求子息，圆者不宜空。占买卖，长者终须折。衣衫则包藏骨肉，葬祭之事宜然。绦带必系纨扇躯，牵缠之事未免。舟车骡马，用之则行。婢仆鸡鹅，呼之便至。金扇之类，收有复展之期。烹调之物，死无再生之理。瓜果问事，破不重圆。棋子求占，散而又聚。荡尘理乱，无逾金篦牙签。释罪沉冤，俱是何章刀笔。壶是主人之礼，觞则空而满，满而复空。锁为君子之防，匙则去而来，来而复去。文章书籍，非小人用之，筐筥犁耙，岂君子用之。惯执鞭所忻慕焉，富而必可求也。能弹琴，复长啸，尔乐亦在其中乎？娱指悬匏，功名少待。折来垂柳，意兴多狂。竹杖龙头，节义一生无愧怍。木锥莺嘴，钻谋万物有刚强。手不释正业经书，自知道德修诸己。问不离九流艺术，意在干戈省厥躬。指庭前向日之花，倏忽坐间移影。点槛外敲风之竹，晨昏静里闻音。君子执笙簧，陶陶其乐，舌鼓终须不免。女人拈针线，刺刺不休，心牵毕竟难蠲。出匣图书行欲方，眼下可分玉石；执来宝剑心从利，手中立剖疑难。羽扇纶巾，须知人自山中去；奇珍异宝，可断人从海上来。百草可活人，不识者不可妄用；六经能裨世，未精者焉敢施为？指盂中之水，久不耗而则倾。顾冶内之金，须知积而复用。事非容易，一首词两下欣逢。学识源渊，几句话三生有幸。执金学道，借服为聚物之囊。割爱延师，重身如无价之宝。明心受业，既行束上之修。寄束言传，莫废师尊之礼。斯其人也，斯其义也，可以为之，非其重焉，非其道焉，孰轻与尔？', '卷之五·拆字杂编', '相字·格物章·总诀'),
('XiangZi_27_01', '物理论', '总诀', '三才始判，八卦攸分。万物不离于五行，群生皆囿于生气。羲皇为文字之祖，苍颉肇书篆之端。鸟迹成章，不过象形会意。云龙结篆，传来竹简添书。秦汉而返，篆隶迭易。钟王既出，楷草出名。其文则见于今，其义犹法于古。人备万物之一数，物物相通。字泄诸人之寸灵，人人各异。欲穷吉凶之朕兆，先格物以致知。且云天为极大，能望而不能亲，毕竟虚空为体；海是最深，可观而不可测，由来消长有时。移山拔树莫如风，片纸遮窗可避。变谷迁陵惟是水，尺筒无底难充。小弹大盘，日之远近，不辨白衣苍狗，云之变化非常。雨本滋长禾苗，不及时，民皆额蹙。雪能冻压草木，如适中，人喜丰年。月行急疾映于江，莫向水中捞捉。星布循环周八极，谁从天上推移。露可比恩，厌浥行人多畏。霞虽似锦，膏肓隐士方宜。皜皜秋阳，炎火再逢为亢害。涓涓冬月，寒冰重见愈凄凉。顽金不畏洪炉，潦水须当堤岸。雾气空濛推障碍，电光倏忽喻浮生。月下美人来，只恐到头成梦。雪中寻客去，犹防中道而归。白露可以寄思，迅雷闻而必变。履霜为忧虞之渐，当慎始焉。临渊有战惕之心，保厥终矣。蝃莫指，闺门之事不宜。霖雨既零，稼穑之家有望。阳春白雪，只属孤音。流水高山，难逢知己。至于岩岩山石，生民具瞻。滚滚源泉，圣贤所乐。瀑布奔冲难收拾，溪流湍激不平宁。风水所以行舟，水涌风狂舟必破。雨露虽能长物，雨霪露结物遭伤。社稷自有人求，关津诚为客阻。烟雾迷林终有见，江河出峡去无回。桃夭取妇相宜，未利于买僮置畜。杨柳送行可折，尤喜于赴试求名。松柏堪问寿年，拟声名则飘香挺秀。丝罗可结姻好，比人品则倚势扳援。荷方出水，渐见舒张。梅可调羹，未免酸涩。李有道傍之苦，榄余齿末之甘。笔墨驱使，时日不长。盆盂装载，团圆难久。绠短汲深求未得，戈长力弱荷难成。屠刀割肉利为官，若问六亲多刑损。利刃剖瓜休作事，如占六甲即生男。无人棺椁必添丁，有印书函终见折。厘等则骨贮匣中，纵有出时还须入。算盘则子盈目下，任凭拨乱却成行。瓦只虑其难全，杯亦防其有缺。席可卷舒，终归人下。伞能开合，定出人头。钓乃小去大来，樵则任重道远。素珠团聚，可串而成。蜡烛风流，不能久固。针线若还缝即合，锹锄如用必然翻。凿则损而为材，亦当有斗，锯乃断而成器，岂谓无长。又若飞走之声沉，亦关人事之休咎。猢狲被系，还家终是无期。鹦鹉在囚，受用只因长舌。鸽乃随人饮啄，纵之仍入樊笼。马虽无胆驰驱，用之不离缰锁。鲤失江湖难变化，燕来堂屋转疑难。诉理伸冤，逢鸦不白。占身问寿，遇鹤修龄。万物纷纭，理则难尽。诸人愿欲，志各不同。若执一端以断人，是犹胶柱鼓瑟。能反三隅而悟理，方称活法圆机。心同金鉴之悬空，妍媸自别。智若玉川之入海，活泼自如。鬼谷子曰：“人动我静，人言我听。”旨哉斯言！胡可忽诸。', '卷之五·拆字杂编', '相字·物理论·总诀'),
('XiangZi_28_01', '五行六神辨别论', '总诀', '先以五行为主，次向字中详祸福。继将六神作用，方观笔迹察原因。生克不容情，莫以字音称独美。宜忌须着意，休将文义恃能言。勿取吉字言吉，当认吉中多忌煞。漫将凶字言凶，须详凶处有元神。假如青龙与白虎同行，求功名大得其宜。如庶人得之，反不免相争之咎。父母与妻子聚面，问赴选难从其志。若游子占之，又可触思远之忧。勾陈最忌小金连，惟恐事无间断。朱雀若逢傍水克，须防祸有牵缠。水在木中流，替人濯垢。木从水中出，脱体犹难。五行全不犯凶神，问自身德建名立。六神动再加吉将，若求官体贵身荣。旧事重新，朱、腾双发动；倾家复创，金、土两重临。微火镕金，难成器皿。弱金克木，反自损伤。求济于人，要看水火会合。营谋于众，还祈土木齐登。金多子多，非土不得。土厚财厚，无火不生。水冷木孤，弟兄难靠。金寒土薄，祖业凋零。玄武形青龙得水，连登两榜。白虎尾朱雀衔金，位列三公。玄武临渊，时中之化雨。青龙捧日，阙下之云腾。水非白而无源，金不秋而失气。有勾陈，难结案头文。见朱雀，忖量堂上语。田下土深，思还故里。月边水盛，意在归湖。玄武居中，出外不宜行陆路。勾陈定位，居官虽在受皇恩。白虎重重，不敢保今年无事。青龙两两，定不是此日燕居。字中见母母无忧，笔下从兄兄定在。水土形青龙翘首，何忧不得功名。木相金白虎当头，毕竟难逃灾害。重重金火不逢时，百事徒劳。叠叠青黄非见日，几番隆替。贵显招土木，万福皆隆。方体隐龙蛇，千祥并集。朱、勾相合，主唇舌干戈之事。龙、虎同行，风云际会之荣。玄武不遇火，阴中不美。腾蛇无水渡，郊外生悲。纯土自能生官，福从天至。寒金不但无禄，灾自幽来。天贵专权，问功名必登黄甲。文书不动，赴场闱定值空亡。问子须求子在爻，占妻定要妻入数。笔迹孤寒金带水，六亲一个难招。字形丰满土生金，百岁百年易盛。看五行之旺弱切记，卜词讼以官鬼为先。定六将之机微须知，占家宅以本命为主。五行俱有，凡谋皆遂。六神不动，万事咸宁。细玩辞占影响，无差毫发。密搜奥义规绳，不爽纤微。', '卷之五·拆字杂编', '相字·五行六神辨别论·总诀'),
('XiangZi_29_01', '金声章', '总诀', '混沌未开，一元含于太极。无形之始，乾坤既判，万物成于文章著见之中。故未有其事，而先有象，可预得其体而兆其来。所以苍颉制字，接云霞蝌蚪之文。至圣著书，采随宜义理而用。一字之善，千古流传。半点之疵，万年不泯。君子哉，非挥毫而莫辨；小人焉，一执笔而即知。是以消长盛衰，因极而知变；吉凶祸福，至诚而见神。写来江汉秋阳，皜皜乎不可尚已。意在螽斯诜羽，绳绳兮与其宜焉。惟存好利喜衰，则落笔终须各别。必欲离尘脱俗，而开首自是不同。若烟雾云霞，则聚散去来神变化；风雷日月，其盈虚消息妙裁成。鹦鹉等禽，人皆云其舌巧；虎豹之类，谁不惧其张威？生息蕃盛者，乃稼穑禾苗；与物浮沉者，是江河湖海。渊中鱼跃，水向东流何沮止？天上鸢飞，日从西落四时同。群兽俱胎之生，独报麟祥之喜；诸禽皆飞腾之物，只言凤德之衰。禽之鸣也噪也，有形小体大之分；兽之利也钝也，有轻清重浊之别。香花灯烛，偏宜于朔望之时；铃铎鼓钟，独可于晨昏之际。点点滴滴，万里征衫游子泪；层层叠叠，九行密线老人心。至于犬豕牛羊，叱之即便去；鸡鱼鹅鸭，欲用则不生。狐貉羔裘，无济于夏；红炉黑炭，偏喜于冬。幽林深圃夜无人，情不诬也；楼阁厅堂时有位，理之必然。琴书剑箱，可断儒生负笈；轻裘肥马，当推志士同袍。墨有渐减之虞，笔恐久坚而弱。书成笔架，几上岷山。写到砚池，寓中闷海。如在其上，秋到一天皆皎月；如在其下，春临遍地产黄金。挥出琵琶，到底是写怨之具；描来箫管，终须为耗气之端。假如云雨雾皆能蔽日之光，天正阴时犹是吉。又若精气神本是扶身之主，人来问病反为凶。水急流清，意偕游鱼；烟飞篆渺，心从云树茫茫。农家落笔，草盛田禾实不足；商者书笺，丝多交易乱如麻。紫绶金章，无者不必写出。蜗名蝇利，有者即便书成。锁钥金汤，必任国家之重寄；羽毛干戚，是祈海甸以清宁。挂锦扬幡，风顺之方必利；舒衾洒帐，雨到之候成欢。礼乐射御书数，如求一艺可执。孝友睦姻任恤，定其六事皆宜。草木逢雨，时生而旺，要详春秋气候。轿马行际，日近而远，亦揆寒暑光阴。试看画饼望梅，何止饥渴？镜花水月，竟是空虚。欲造字相之微，请明章中之理。', '卷之五·拆字杂编', '相字·金声章·总诀'),
('XiangZi_30_01', '浑天甲子定局', '总诀', '（本版正文为整页图象、文字阙如；据别本补录全文，见 图象补录·TX_HUN_TIAN_JIA_ZI。正文『以上四宫属阳，皆从顺数／以上四宫属阴，皆从逆数』『右诀从下念上，一如点画卦爻法』。）', '卷之五·拆字杂编', '相字·浑天甲子定局·总诀'),
('XiangZi_31_01', '后天时方', '总诀', '（本版正文阙如，仅存校勘记『①「败」，堂本作「散」②「生」，校本作「位」』；据别本补录全文，见 图象补录·TX_HOU_TIAN_SHI_FANG。）', '卷之五·拆字杂编', '相字·后天时方·总诀'),
('XiangZi_32_01', '干支辨', '甲乙', '直长为甲亦为寅，细短均为乙卯身。孤直心钩兼湿木，干支无位不须论。假如车字中央一直，彻上彻下，强健无损，则属阳，所以为甲木、寅木。余皆仿此。如幸字上一直下一直，皆短弱属阴，所以作乙木、卯木论也。凡一直，细弱不健，即长如车之直，亦作乙卯木看。其心钩舟船木，并三横两短木，一概不在干支论，因其不正故也。', '卷之四·字画指迷·干支辨', '相字·干支辨·甲乙'),
('XiangZi_32_02', '干支辨', '丙丁', '撇长丙巳短为丁，午火同居短撇中。八字腾蛇兼四点，天干不合地支冲。假如庐字撇长，则取为丙火、巳火用。丙巳属阳，故用撇长者当之。余仿此。', '卷之四·字画指迷·干支辨', '相字·干支辨·丙丁'),
('XiangZi_32_03', '干支辨', '戊己', '横中有直戊居中，画短横轻作己身。末点勾陈皆丑未，长而粗者戊辰同。', '卷之四·字画指迷·干支辨', '相字·干支辨·戊己'),
('XiangZi_32_04', '干支辨', '庚辛', '口字为金亦作申，挑从酉用捺从辛。空头顽钝囊金妙，不在干支数内寻。', '卷之四·字画指迷·干支辨', '相字·干支辨·庚辛'),
('XiangZi_32_05', '干支辨', '壬癸', '点在当头作癸称，腹中为子要分明。点足为壬腰在亥，余皆野水不同群。假如「文」字一点，即为癸水。癸水乃雨露之源，因在上故也。余仿此。', '卷之四·字画指迷·干支辨', '相字·干支辨·壬癸'),
('XiangZi_40_01', '齐景至理论', '总诀', '天下之妙，无过一理。理既能明，在乎明学。学者穷究，莫难乎性。性既明达，其理昭然。且苍颉始制之时，观迹成象，以之运用，应变随机。且释老梵经，王勃佛记，迨乎今飞轮宝藏之内，既深且密，非高士莫得而闻。何由睹之？其汉高有荣阳之围，以木生火，终不能灭。有人梦腹上生松，丝悬山下，后为幽州刺史。松为十八公，不十为卒。《春秋》说“十四心为德”，《国志》云“口在天为吴”。《晋书》：黄头小人为恭，以人负吉为造。八女之解安禄山，两角女子绿衣裳。端坐太行邀君主，一正之月能灭亡。正月也。郭璞云：永昌有昌之象。其后昌隆。罗，四维也。其偶如此。且人禀阴阳造化，凭五行妙思，一言一语，一动一静，然后挥毫落楮，点画勾拔，岂不从于善恶？得之于心，悬之于手，心正则笔正，心乱则笔乱。笔正则万物咸安，笔乱则千灾竞起。由是考之，其来有自。达者，以理晓；昧者，以字拘。难莫难于立意，贵于言辞。立意须在一门，言词务在心中。余幼亲师友，温故知新，志在取进场屋，为祖宗之光。遂乃屈身假道，每以诗酒自娱。渡江乘兴，偶信卜于岩谷。观溪山之清流，闻禽鸟之好音，殆非人世。忽见一人道貌古怪，披头跣足，踞坐磻石之上。余由是坐之于侧，良久交谈之际，询余曰：“子非齐景乎？”予惊讶，预知姓名，疑其必异人也，遂答之曰：“然。”异人曰：“混沌判肇，苍颉制字者，余也。自传书契于天下，天下大定。后登天为东华帝君。今居于此，乃东华洞天。余曾有奇篇，昔付谢石，今当付汝。今子之来，可熟记速去。不然，尘世更矣。”于是拜而受之，退而观其奥妙，乃《玄黄妙诀神机》。解字之文，得其方妙，如谷之应声，善恶悉见，祸福显然，定死生于先知，决狐疑于预见，后之学者幸珍重之。', '卷之四·字画指迷', '相字·齐景至理论·总诀'),
('XiangZi_41_01', '字画经验', '总诀', '敷字：昔在任宰，请折之，云此字十日内放笔。果以十日罢任。家字：凡人书此，家宅不宁。空字头，豕应在亥月者也。荆字：艹而刑，不利小人，大宜君子。砚字：有一字天，出之乱尔，见名之兆。典字：曲折多，四七日有兴进之兆。贵人必加官进禄，雅宜便，四十日有进纳之喜。果字：凡事善果披剃，盖口中无才，又云进小口。马字：昔有马雅官，写马字无点，马无足不可动。来字：来带两人之木，皆来见信，行人来应，三人同来，财午未年发。葵字：逢春发生，又占名利，逢癸可发，占病不宜，廿日有惊恐之兆。但字：如日初生，常人主孤，凡事未如意，十日身坦然。谦字：故人嫌，盖无廉耻，目下有事，多是非。亨字：高未高，了未了，须防小人，不足及外孝，不祥。达字：二十日未达，即日并不顺，少喜多忧。奇字：占婚奇偶未谐，应十日难，为兄弟事不全。俊字：一住一利，交友难为。父兄反覆，文书千连变易。凶。常字：占病堂上人灾，有异姓异母。上有堂字头，下有哭字头。每字：昔曹石遣人相此字，异日必为人母。后果然。城字：逢丁戊日，六神动，忌丁戊日，田土不足，进力成功。池字：凡事拖延有日，逢蛇必利，盖添虫为蛇。春字：宋高宗写此字时，秦桧用事。石云：秦头太重，压日无光。桧闻言召而遣之。一字：土字一字，王也。益字：有吏人书益字，廿八日有血光之厄。至期果然。田字：有人出此，相言：直看是王，横看是王，必主大贵。', '卷之四·字画指迷', '相字·字画经验·总诀'),
('XiangZi_42_01', '字体诗诀', '总诀', '天字及二人，作事必有因。一天能庇盖，初主好安身。地字如多理，从此出他乡。心如蛇口毒，去就尽无妨。人字无凶祸，文书有人来。主人自卓立，凡事保和谐。金字得人力，屋下有多财。小人多不足，凡事要安排。木字人未到，初生六害临。未年财禄好，切莫要休心。水字可求望，中妨有是非。文书中有救，出入总相宜。火字小人相，中人发大财。灾忧须见过，日下有人来。土字日下旺，田财尽见之。穿心多不足，骨肉主分离。东字正好动，凡事早求人。牵连须有事，财禄自交欣。西字宜迁改，为事忌恶人。心情虽洒落，百事懒栖身。南字穿心重，还教骨肉轻。凡事却有幸，田土不安宁。北字本比和，不宜分彼此。欲休尚未休，问病必见死。身字主己事，侧伴更添弓。常藉人举荐，仍欣财禄丰。心字无非大，秋初阴小灾。小人多不足，夏见必灾来。头来须鄙衰，发可却近贵。要过子丑前，凡事皆顺利。病来如何疾，木命最非宜。过了丙丁日，方知定不危。言字如何拆？人来有信音。平生多计较，喜吉事应临。行字问出入，须知未可行。不如姑少待，方免有灾惊。到字若来推，出入尚颠倒。虽然吉未成，却于财上好。得来问日下，宁免带勾陈。凡事未分付，行人信不真。开字无分付，营谋尚未安。欲开开不得，进退两皆难。附字问行人，行人犹在路。为事却无凶，更喜有分付。事字事难了，更又带勾陈。手脚仍多犯，月中方可人。卜方求测事，停笔好推详。上下俱不足，所为宜不祥。望字逢寅日，所谋应可成。主须不正当，却喜有功名。福字来求测，须防不足来。相连祸逼迫，一口又兴灾。禄字无祖产，当知有五成。小人生不足，小口有灾惊。贵字多近贵，六六发田财。出入须无阻，宜防失落灾。用字主财用，有事必经州。谁识阴人事，姓王又姓周。康字未康泰，要防阴小灾。所为多不逮，财禄亦难来。宁字占家宅，家和人口增。财于中主发，目下尚伶仃。吉字来占问，反教吉又凶。因缘犹未就，作事每无终。宜字事且且，须知在目前。官非便了当，家下亦安然。似字众人事，所为应不成。独嫌人力短，从众则堪行。多字宜迁动，死中还得生。事成人侈靡，两日过方明。古字多还吉，难逃刑克灾。虽然似喜吉，口舌却终来。洪宜人共活，火命根基别。事还牵制多，应是离祖业。香字忌暗箭，木上是非来。十八二十八，好看音信回。清字贵人顺，财来蓄积盈。阴人是非事，不净更多年。虚惟头似虎，未免有虚惊。凡事亦可虑，仍妨家不宁。远字事多达，行人有信音。为事既皆遂，喜吉又来临。同字如难测，商量亦未然。两旬事方足，尚恐不周圆。众字人共事，亦多生是非。所为应不敛，小口有灾危。飞字须可喜，反覆亦多非。意有飞腾象，求名事即宜。秀字多不实，无事亦孤刑。五五加一岁，还生事不宁。风字事无宁，逢秋愈不吉。疾多风癣攻，更防辰戌日。天字已成天，亦多吞噬心。事皆蒙庇盖，行主二人临。元字二十日，所为应有成。平生刑克重，兀兀不安宁。秋字秋方吉，小人多是非。须知和气散，目下不为宜。申字是非长，道理亦有破。终然屈不伸，谋事难为祸。甲字利姓黄，求名黄甲宜。只恐田土上，还惹是和非。川字如来问，当知有重灾。仍防三十日，不足事还来。墟字若问事，虎头蛇尾惊。有人为遮盖，田土不安宁。辰字如写成，主有变化象。进退虽两难，功名却可望。青字事未顺，须知不静多。贵人仍不足，日久始安和。三字多迁改，为事亦无主。当知二生三，水由一生二。人如来问测，分字亦安让。凡事多费解，仍防公扰忧。字须有学识，初主似空虚。家下不了事，名因女子中。士为大夫体，末免犯穿心。拮括是非散，番多吉事临。', '卷之四·字画指迷', '相字·字体诗诀·总诀'),
('XiangZi_43_01', '四季水笔', '总诀', '四季水笔春水昏浊　夏水枯涸　秋水澄清　冬水凝结水为财，忌居乾、兑、坎。、、、勹、点不为杀，必为贵人。', '卷之四·字画指迷', '相字·四季水笔·总诀'),
('XiangZi_44_01', '画有阴阳', '总诀', '画有阴阳长中有短为阳中阴，短中有长为阴中阳。粗细轻重，以此为例。阳中有阴则佳，阴中有阳反凶。壬字头画，是阳中有阴。任字头画，是阴中有阳。水笔不流，流则不佳。戴流珠，名映星，小人囚系。取福下至上一三，取祸上至下一三。', '卷之四·字画指迷', '相字·画有阴阳·总诀'),
('XiangZi_45_01', '笔法筌蹄', '总诀', '凡书字法，有浓淡、肥瘦、长短、阔狭、反覆、顺逆、曲直、高低、小大、软硬、开合、清浊、虚实、凹凸、平正、斜侧、圆满、直牵、明白、轻快、稳重、跳跃、勾挽、破碎、枯槁、尖削、倒乱、鹘突、孤露、交加、肥满、尖瘦、刚建、精神、艳冶、气势、衰弱、小巧、软满、老硬、骨棱、草率、开阖之分，各有一体，难以尽述。学者变化，知机其神。', '卷之四·字画指迷', '相字·笔法筌蹄·总诀'),
('XiangZi_46_01', '奴婢', '总诀', '奴　婢恰似霜天一叶飞，画如木檐两头垂。画轻点重君须记，画定前趋后拥儿。', '卷之四·字画指迷', '相字·奴婢·总诀'),
('XiangZi_47_01', '阴人', '总诀', '阴　人阴人下笔意如何，只为多羞胆气虚。起处恰如争嘴样，却来下笔定徐徐。', '卷之四·字画指迷', '相字·阴人·总诀'),
('XiangZi_48_01', '隔手', '总诀', '隔　手隔手书来仔细详，见他纸墨字光芒。更看体骨苏黄格，淡有精神是贵郎。', '卷之四·字画指迷', '相字·隔手·总诀'),
('XiangZi_49_01', '笔画长短', '总诀', '笔画长短如“吉”字，上作士字，终作士人。如作土字，乃口在下，问病必死。若身命属木，自身无妨。屋下木土生，不过十日必亡。如“常”字，上作小字，只是主家内小口灾，略不为大害。若上草作小，如此写，乃是灾字头，中是门字，下是吊字，主其人大灾患临头，吊客入门，大凶。然亦须仔细仍观人之气色。象人而言，如土人，气色黑恶，其人必退，若土命者，必死，俱不过十日。', '卷之四·字画指迷', '相字·笔画长短·总诀'),
('XiangZi_50_01', '笔画犯煞', '总诀', '笔画犯煞——本版存目（诸式多为图象，诀文漫漶）：凤鳞、断伏、活法、用煞、连图带、曰隔伏、丁欹伏、冲伏、悬针、流金、活金、乙伏曲、曲伏、口死金、活火、死火、腾蛇、死土、蛇土、力隔伏。（共二十式；原刻有目无诀，照目存录，不臆补。）', '卷之四·字画指迷', '相字·笔画犯煞·总诀'),
('XiangZi_51_01', '七言作用歌', '总诀', '七言作用歌用神加直五行真，谋望营为百事成。疾病官非兼口舌，纵逢凶处不成凶。（凡金木水火土真字，皆宜用，乃五行真遂，诸事皆利。）年干所属是科名，禾斗皆为首占星。有此求名皆遂意，如无考试定成空。（凡占功名，必要科名入数，再兼官鬼文书动而旺相，功名可成。如无，科名莫许。）求谋之数禄神临，始断今科考事兴。若遇科名同在数，自然高荐遂生平。（禄神即甲禄在寅是也。）有田有日会神兴，见客逢人不必寻。马星原是弯弓脚，四点原来用亦同。（凡谒贵寻人，俱要会神，行人俱要马星妙。）士头口体喜神俱，嫁娶婚姻百事宜。只怕重重见火土，许多克伐反非奇。（“士”属土怕木，“口”属金怕火，所以见木土反非奇也。）笔清墨秀琢磨深，方正无偏必缙绅。疾走龙蛇心志远，行藏慷慨位三公。又字兼骨格有精神，窗下工夫用得深。笔迹丰肥金见火，诗书队里久陶镕。又金木重重见贵神，笔挥清楚主聪明。耸直一行冲宝盖，富贵荣华日日新。又方圆端正笔无尘，年少登科入翰林。只恐弱木逢金克，缠身病疾不明萌。又木形之字有精神，可云发达耀门庭。火多年少心多燥，水盛为人智必清。又一直居中勇更明，少年黾勉得功名。末笔再逢金土厚，为官享禄更廉明。又笔端势小事无成，粗俗须知业不精。起头落尾如莺嘴，心里奸谋刻薄人。又土形之字活而圆，用神清楚是英贤。笔底到头无间断，一家荣耀有余钱。又字贬无神笔更联，公门吏卒度余年。勉强操觚无实学，欺人长者被人嫌。又战兢惕厉若临渊，静里修持反有年。写笔果然无俗气，终须榜上有名填。又日月当头笔迹强，精神骨格字无伤。国家梁柱何消息，更有奇衷佐圣疆。又衣食身旁黑带浓，最嫌软弱与无神。字中人口如枯暗，莫待长年主恶终。又下笔头高志必雄，落头不是正经人。尖头秃尾人无智，老死衙门不得名。又一字忙忙写未全，有头无尾不须言。作事率然多失错，琢磨早失在当年。又字无骨格少精神，一生多耗病沉沉。问名带草索连就，满腹文章亦落空。又草写香花定主贫，弱软干枯受苦辛。于中若是为官客，几日新鲜一旦倾。', '卷之五·拆字杂编', '相字·七言作用歌·总诀'),
('XiangZi_52_01', '比例歌', '总诀', '比例歌一斗日来占事不差，无心书鬼状元家。功名第二推为政，舜字登科作探花。二辰时执笔若书才，大振声名事必来。正午书言真是许，水旁写半见泮开。三逢三书八士能成，照例推之理便通。申车不乱推联捷，数逢三一始为真。四二人同到独书余，一定其间事必徐。问失执金知是铁，始为一举反三隅。此例之类，不过详其理也。暂录四首，为后学之门。余仿此。', '卷之五·拆字杂编', '相字·比例歌·总诀'),
('XiangZi_53_01', '西江月', '总诀', '西江月要见卦爻衰旺，端详其内章图。欲知事物识天机，细把《玄黄篇》记。临占观形察物，叶音即义断之。若逢王者世为奇，君免猜疑直示。', '卷之五·拆字杂编', '相字·西江月·总诀'),
('XiangZi_54_01', '易理玄微', '总诀', '易理玄微昔李淳风占赤黑二马入河，人问二马何先起。有人演得离卦云：“离为火，火赤色，赤马先起。”李曰：“火未然，烟先发，黑马先起。”果然。', '卷之五·拆字杂编', '相字·易理玄微·总诀'),
('XiangZi_55_01', '断扇占', '总诀', '断扇占昔有一妇，其夫久客不归，因请李淳风先生处求断易数。适值他出，问其子，其子见妇手中携一扇，其扇面忽然落地，因断曰：“骨肉分离，不得相见矣。”妇泣而归，恰路遇李淳风先生。妇诉其故，李断曰：“穿衣见父，脱衣见夫。不妨，尔夫今日必到。”将晚，果然至家。可见各解不同，其断精微若此。', '卷之五·拆字杂编', '相字·断扇占·总诀'),
('XiangZi_56_01', '买香占', '总诀', '买香占酉年八月二十五日午时，有杨客买香。康节曰：“此香非沉香。”客曰：“此香真不可及。”康节曰：“火中有水，水泽之木，非沉香也。恐是久阴之木，用汤药煮之。”客怒而去。半月后有宾朋至，云是清尾人家做道场，沉香伪而不香。康节曰：“香是何人带来，但问其故，我已先知之矣。”伯温令人去问，果是杨客。康节曰：“前日到门首，因观之。未问之前先失手，其香坠地，故取年月日时占之，得睽之噬嗑。暌下卦属兑，兑为泽。噬嗑下卦属震，震为木，乃水泽之木，即非沉香。睽卦上互得坎，坎为水；下互得离，离为火。上有水即汤，噬嗑卦上互见坎，坎为水，下互见艮，艮为山，中有水，亦泽之象。此乃水泽久损污湿之木，以汤煮之。此理可晓。从此大小事，不可不较其时也。”', '卷之五·拆字杂编', '相字·买香占·总诀'),
('XiangZi_57_01', '古人相字', '总诀', '古人相字昔谢石以拆字名天下，宋高宗私行遇石，以杖于土上书一“一”字，令相之。石思之曰：“土上加一画成王字，必非庶人。”疑信之间，帝又画一“问”字，令相之。为田土所梗，两旁俱斜侧飘飞。石尤惊曰：“左看是君字，右看是君字，必是主上。”遂下拜。上曰：“毋多言。”石俯伏谢恩，帝因召官之。次日，召见偏殿，书一“春”字命相。石奏曰：“秦头太重，压日无光。”上默然。时秦桧弄权，适忤桧，竟贬之边远。途间遇一女子，云能拆字。石怪曰：“世间复有如我拆字者乎？”遂书“谢”字，令相之。女曰：“不过一术士耳。”石曰：“何故？”女曰：“是寸言中立身尔。”石又书一“皮”字。女曰：“石逢皮即破矣。”盖押石之卒即皮姓也。石大惊服，曰：“吾亦能相字，汝可书字，吾相之。”女曰：“吾在此即字矣。请相。”石曰：“人傍山立，即仙字。汝非仙乎？”女笑而忽失。盖世有妙术，术有妙理，在人心耳。然数定，固莫能逃也。后石竟不返。张乘槎善相字，浙江旧有拱北楼，王参政莅淅，改为“来豐楼”。初揭匾，命槎占之，槎曰：“殀矣！尚何占哉！”是晚，讣音果至。异日叩之故，槎曰：“豐字之形，山者墓所也。二丰者，冢上树也。豆者，祭器也。其兆如此，岂非死乎！”刘尝心有所欲占，延槎而不言其事，但令射之，以验其术。槎曰：“书一字方可占。”适有小学生在旁习字，正写《千字文》，至“德建名立”一句，刘就指“德”字令占之。槎曰：“子欲占行人耳。”刘曰：“然。何时当至？”槎曰：“自今十四日必来。”刘曰：“恐事不了，不肯来。”槎曰：“一心要行。悉如所占。”刘问故，槎曰：“德字双立人，乃行人也，故知占行。旁有十四字头，故云十四日。其下又有一心字形，所以云一心要来也。”裴晋公征吴元济，掘地得一石，有字云：“鸡未肥，酒未熟。”相字者解曰：“鸡未肥，无肉也，为己；酒未熟，无水也，酒去‘氵’为酉。破贼在己酉。”果然。唐僖宗改为广明元年。相字者曰：“昔有一人，自崖下出来，姓黄氏，左足踏日，右足踏月，自此天下被扰也。”是年黄巢在长安作乱，天下不安。宋太宗改元太平兴国。相字者曰：“太平二字乃一人六十寿也。”太宗果享六十而崩。周尚干年终将换桃符，制十数联，皆不惬意。周梅坡扶箕降紫姑仙，得两句云：“门无公事往来少，家有阴功子孙多。”甚喜，大书于门。相字者曰：“每句用上三字，其兆不祥。”上句云“门无公”，是年尚干卒于官，乃父致政亦卒，乃兄卒，俱无子。“门无公”、“家有阴”，兆于先矣。', '卷之五·拆字杂编', '相字·古人相字·总诀'),
('XiangZi_58_01', '断富贵贫贱要诀', '总诀', '断富贵贫贱要诀凡字写得健壮，其人必发大财，有田土好产。二画一点者，多贵为官食禄，不然亦近贵。才字中或多了一画、一撇、一捺，亦主横发财禄多，遇异贵，得成名利。或少了一画、一撇、一捺，其人破荡弃祖，自立成败。如“名”、“目”字，写得如法正当，无缺折者，其人有名分。笔多清贵虚名。上笔多，富而贵。字中有画当短而长，其人慷慨，会使钱近贵。字画直长而短，其人鄙吝，一钱不使。字有悬针，或直落尖，皆刑六亲，伤害妻子。横画两头尖者，伤妻。直落两头尖者，伤子。字捩画少者，孤捩。画不沾者亦孤，为僧或九流。如见十字两头尖者，穿心六害，刑妻子兄弟，骨肉皆空。字中点多者，主人淫滥漂荡，贪花好色，居止不定。十字下面脚不失者，晚得子方。如见上一画重者，平头杀，亦难为六亲。轻者初年不足，中、末如意。或点重者，为商旅发财，离乡失井，出外卓立。若水命、金命见点画轻者，或早年有水灾，捩者无安身之地，作事成败，主恶死不善终。直落多者，聪明机巧，为手艺之人，白手求财。画多者，必有心胁脾胃之疾。木多有心气之疾，晚年见之。写口字或四围有口开者，有口舌，旬日见之，或破财不足。发字头见者，末主发财。一字分作三截，上中下三主断之。士头文脚，主有文学。金笔灵，或见于干戈字脚者，必是用武之士。凡妇人写来字画不正者，必是偏室，或带三点，必有动意，如三之类。凡写字之人偶然出了笔头，此事破而无成。或近火边写字，必心下不宁。或写字用破器添砚水，家破人亡。或写字时，犬来左右吠，不吉。或取纸来写破碎者，主有口舌。或写字时猫叫，此人有添丁之喜。或在楼上写来问者，主有重叠之事。或在船上写来问者，主有虚惊。或扇上写来问者，夏吉冬不吉。如本命属金，金笔多者贵，土笔多者富。五行生克亦然。余仿此。', '卷之五·拆字杂编', '相字·断富贵贫贱要诀·总诀'),
('XiangZi_59_01', '五行相生地支', '总诀', '五行相生地支木生在亥火生于寅金生于巳水土长生居申', '卷之五·拆字杂编', '相字·五行相生地支·总诀'),
('XiangZi_60_01', '天干地支所属五行', '总诀', '天干地支所属五行甲乙寅卯属木丙丁巳午属火戊己辰戌丑未属土庚申辛酉属金壬癸亥子属水', '卷之五·拆字杂编', '相字·天干地支所属五行·总诀'),
('XiangZi_61_01', '论八卦性情', '总诀', '论八卦性情乾健也坤顺也震起也艮止也坎陷也离丽也兑说也巽入也', '卷之五·拆字杂编', '相字·论八卦性情·总诀'),
('XiangZi_62_01', '八卦取象', '总诀', '八卦取象乾为天坤为地震为雷巽为风坎为水离为火艮为山兑为泽', '卷之五·拆字杂编', '相字·八卦取象·总诀'),
('XiangZi_63_01', '六十甲子纳音', '总诀', '歌甲子乙丑海中金，丙寅丁卯炉中火。戊辰己巳大林木，庚午辛未路旁土。壬申癸酉剑锋金，甲戌乙亥山头火。丙子丁丑涧下水，戊寅己卯城头土。庚辰辛巳白腊金，壬午癸未杨柳木。甲申乙酉井泉水，丙戌丁亥屋上土。戊子己丑霹雳火，庚寅辛卯松柏木。壬辰癸巳长流水，甲午乙未沙中金。丙申丁酉山下火，戊戌己亥平地木。庚子辛丑壁上土，壬寅癸卯金箔金。甲辰乙巳覆灯火，丙午丁未天河水。戊申己酉大驿土，庚戌辛亥钗钏金。壬子癸丑桑柘木，甲寅乙卯大溪水。丙辰丁巳沙中土，戊午己未天上火。庚申辛酉石榴木，壬戌癸亥大海水。', '卷之五·拆字杂编', '相字·六十甲子纳音·总诀'),
('XiangZi_64_01', '五行四时旺相休囚表', '总诀', '（本版正文为整页图象、文字阙如；据别本补录全文，见 图象补录·TX_WU_XING_SI_SHI。）', '卷之五·拆字杂编', '相字·五行四时旺相休囚表·总诀');

-- ============================================================================
-- 11. 附录·渔樵对问 / 宋史·邵雍传（附录文献；第26轮补录）
--    依《本体顶层设计》原著范围（附录：一撮金·渔樵对问·宋史·邵雍传）；
--    一撮金承载于 yicuo_jin_yao（第 8b 表），此表承载余二篇全文（唯一真源）。
-- ============================================================================
INSERT INTO appendix_text (name, work_name, section_index, section_topic, text_body, source_ref, label) VALUES
('ATXT_YQ_01', '渔樵对问', 1, '渔者', '渔者垂钓于伊水之上。樵者过之，弛担息肩，坐于磐石之上，而问于渔者。', '附录·渔樵对问', '附录·渔樵对问·第1则'),
('ATXT_YQ_02', '渔樵对问', 2, '答', '曰：“鱼可钩取乎？”', '附录·渔樵对问', '附录·渔樵对问·第2则'),
('ATXT_YQ_03', '渔樵对问', 3, '答', '曰：“然。”', '附录·渔樵对问', '附录·渔樵对问·第3则'),
('ATXT_YQ_04', '渔樵对问', 4, '答', '曰：“钩非饵可乎？”', '附录·渔樵对问', '附录·渔樵对问·第4则'),
('ATXT_YQ_05', '渔樵对问', 5, '答', '曰：“否。”', '附录·渔樵对问', '附录·渔樵对问·第5则'),
('ATXT_YQ_06', '渔樵对问', 6, '答', '曰：“非钩也，饵也。鱼利食而见害，人利鱼而蒙利，其利同也，其害异也。敢问何故？”', '附录·渔樵对问', '附录·渔樵对问·第6则'),
('ATXT_YQ_07', '渔樵对问', 7, '渔者', '渔者曰：“子樵者也，与吾异治，安得侵吾事乎？然亦可以为子试言之。彼之利，犹此之利也；彼之害，亦犹此之害也。子知其小，未知其大。鱼之利食，吾亦利乎食也；鱼之害食，吾亦害乎食也。子知鱼终日得食为利，又安知鱼终日不得食为害？如是，则食之害也重，而钩之害也轻。子知吾终日得鱼为利，又安知吾终日不得鱼不为害也？如是，则吾之害也重，鱼之害也轻。以鱼之一身，当人之食，是鱼之害多矣；以人之一身，当鱼之一食，则人之害亦多矣。又安知钓乎大江大海，则无易地之患焉？鱼利乎水，人利乎陆，水与陆异，其利一也；鱼害乎饵，人害乎财，饵与财异，其害一也。又何必分乎彼此哉！子之言，体也，独不知用尔。”', '附录·渔樵对问', '附录·渔樵对问·第7则'),
('ATXT_YQ_08', '渔樵对问', 8, '樵者', '樵者又问曰：“鱼可生食乎？”', '附录·渔樵对问', '附录·渔樵对问·第8则'),
('ATXT_YQ_09', '渔樵对问', 9, '答', '曰：“烹之可也。”', '附录·渔樵对问', '附录·渔樵对问·第9则'),
('ATXT_YQ_10', '渔樵对问', 10, '答', '曰：“必吾薪济子之鱼乎？”', '附录·渔樵对问', '附录·渔樵对问·第10则'),
('ATXT_YQ_11', '渔樵对问', 11, '答', '曰：“然。”', '附录·渔樵对问', '附录·渔樵对问·第11则'),
('ATXT_YQ_12', '渔樵对问', 12, '答', '曰：“吾知有用乎子矣。”', '附录·渔樵对问', '附录·渔樵对问·第12则'),
('ATXT_YQ_13', '渔樵对问', 13, '答', '曰：“然则子知子之薪，能济吾之鱼，不知子之薪所以能济吾之鱼也。薪之能济鱼久矣，不待子而后知。苟世未知火之能用薪，则子之薪虽积丘山，独且奈何哉？”', '附录·渔樵对问', '附录·渔樵对问·第13则'),
('ATXT_YQ_14', '渔樵对问', 14, '樵者', '樵者曰：“愿闻其方。”', '附录·渔樵对问', '附录·渔樵对问·第14则'),
('ATXT_YQ_15', '渔樵对问', 15, '答', '曰：“火生于动，水生于静。动静之相生，水火之相息。水火，用也；草木，体也。用生于利，体生于害。利害见乎情，体用隐乎性。一性一情，圣人能成。子之薪犹吾之鱼，微火则皆为腐臭败坏，而无所用矣，又安能养人七尺之躯哉？”', '附录·渔樵对问', '附录·渔樵对问·第15则'),
('ATXT_YQ_16', '渔樵对问', 16, '樵者', '樵者曰：“火之功大于薪，固已知之矣。敢问善灼物，何必待薪而后传？”', '附录·渔樵对问', '附录·渔樵对问·第16则'),
('ATXT_YQ_17', '渔樵对问', 17, '答', '曰：“薪，火之体也。火，薪之用也。火无体，待薪然后为体；薪无用，待火然后为用。是故凡有体之物，皆可焚之矣。”', '附录·渔樵对问', '附录·渔樵对问·第17则'),
('ATXT_YQ_18', '渔樵对问', 18, '答', '曰：“水有体乎？”', '附录·渔樵对问', '附录·渔樵对问·第18则'),
('ATXT_YQ_19', '渔樵对问', 19, '答', '曰：“然。”', '附录·渔樵对问', '附录·渔樵对问·第19则'),
('ATXT_YQ_20', '渔樵对问', 20, '答', '曰：“火能焚水乎？”', '附录·渔樵对问', '附录·渔樵对问·第20则'),
('ATXT_YQ_21', '渔樵对问', 21, '答', '曰：“火之性，能迎而不能随，故灭。水之体，能随而不能迎，故热。是故有温泉而无寒火，相息之谓也。”', '附录·渔樵对问', '附录·渔樵对问·第21则'),
('ATXT_YQ_22', '渔樵对问', 22, '答', '曰：“火之道生于用，亦有体乎？”', '附录·渔樵对问', '附录·渔樵对问·第22则'),
('ATXT_YQ_23', '渔樵对问', 23, '答', '曰：“火以用为本，以体为末，故动。水以体为本，以用为末，故静。是火亦有体，水亦有用也，故能相济又能相息。非独水火则然，天下之事皆然，在乎用之何如尔。”', '附录·渔樵对问', '附录·渔樵对问·第23则'),
('ATXT_YQ_24', '渔樵对问', 24, '樵者', '樵者曰：“用可得闻乎？”', '附录·渔樵对问', '附录·渔樵对问·第24则'),
('ATXT_YQ_25', '渔樵对问', 25, '答', '曰：“可以意得者，物之性也。可以言传者，物之情也。可以象求者，物之形也。可以数取者，物之体也。用也者，妙万物为言者也，可以意得，而不可以言传。”', '附录·渔樵对问', '附录·渔樵对问·第25则'),
('ATXT_YQ_26', '渔樵对问', 26, '答', '曰：“不可以言传，则子恶得而知之乎？”', '附录·渔樵对问', '附录·渔樵对问·第26则'),
('ATXT_YQ_27', '渔樵对问', 27, '答', '曰：“吾所以得而知之者，固不能言传，非独吾不能传之以言，圣人亦不能传之以言也。”', '附录·渔樵对问', '附录·渔樵对问·第27则'),
('ATXT_YQ_28', '渔樵对问', 28, '答', '曰：“圣人既不能传之以言，则六经非言也耶？”', '附录·渔樵对问', '附录·渔樵对问·第28则'),
('ATXT_YQ_29', '渔樵对问', 29, '答', '曰：“时然后言，何言之有？”', '附录·渔樵对问', '附录·渔樵对问·第29则'),
('ATXT_YQ_30', '渔樵对问', 30, '樵者', '樵者赞曰：“天地之道备于人，万物之道备于身，众妙之道备于神，天下之能事毕矣，又何思何虑！吾而今而后，知事心践形之为大。不及子之门，则几至于殆矣。”', '附录·渔樵对问', '附录·渔樵对问·第30则'),
('ATXT_YQ_31', '渔樵对问', 31, '叙', '乃析薪烹鱼而食之，饫而论《易》。', '附录·渔樵对问', '附录·渔樵对问·第31则'),
('ATXT_YQ_32', '渔樵对问', 32, '渔者', '渔者与樵者游于伊水之上。渔者叹曰：“熙熙乎万物之多，而未始有杂。吾知游乎天地之间，万物皆可以无心而致之矣。非子则吾孰与归焉？”', '附录·渔樵对问', '附录·渔樵对问·第32则'),
('ATXT_YQ_33', '渔樵对问', 33, '樵者', '樵者曰：“敢问无心致天地万物之方？”', '附录·渔樵对问', '附录·渔樵对问·第33则'),
('ATXT_YQ_34', '渔樵对问', 34, '渔者', '渔者曰：“无心者，无意之谓也。无意之意，不我物也。不我物，然后定能物物。”', '附录·渔樵对问', '附录·渔樵对问·第34则'),
('ATXT_YQ_35', '渔樵对问', 35, '答', '曰：“何谓我，何谓物？”', '附录·渔樵对问', '附录·渔樵对问·第35则'),
('ATXT_YQ_36', '渔樵对问', 36, '答', '曰：“以我徇物，则我亦物也；以物徇我，则物亦我也。我物皆致，意由是明。天地亦万物也，何天地之有焉？万物亦天地也，何万物之有焉？万物亦我也，何万物之有焉？我亦万物也，何我之有焉？何物不我？何我不物？如是则可以宰天地，可以司鬼神，而况于人乎？况于物乎？”', '附录·渔樵对问', '附录·渔樵对问·第36则'),
('ATXT_YQ_37', '渔樵对问', 37, '樵者', '樵者问渔者曰：“天何依？”', '附录·渔樵对问', '附录·渔樵对问·第37则'),
('ATXT_YQ_38', '渔樵对问', 38, '答', '曰：“依乎地。”', '附录·渔樵对问', '附录·渔樵对问·第38则'),
('ATXT_YQ_39', '渔樵对问', 39, '答', '曰：“地何附？”', '附录·渔樵对问', '附录·渔樵对问·第39则'),
('ATXT_YQ_40', '渔樵对问', 40, '答', '曰：“附乎天。”', '附录·渔樵对问', '附录·渔樵对问·第40则'),
('ATXT_YQ_41', '渔樵对问', 41, '答', '曰：“然则天地何依何附？”', '附录·渔樵对问', '附录·渔樵对问·第41则'),
('ATXT_YQ_42', '渔樵对问', 42, '答', '曰：“自相依附。天依形，地附气。其形也有涯，其气也无涯。有无之相生，形气之相息。终则有始，终始之间，其天地之所存乎？天以用为本，以体为末；地以体为本，以用为末。利用出入之谓神，名体有无之谓圣。唯神与圣，能参乎天地者也。小人则日用而不知，故有害生实丧之患也。夫名也者，实之客也；利也者，害之主也。名生于不足，利丧于有余。害生于有余，实丧于不足。此理之常也。养身者必以利，贪夫则以身殉，故有害生焉。立身必以名，众人则以身殉名，故有实丧焉。窃人之财谓之盗，其始取之也，唯恐其不多也。及其败露也，唯恐其多矣。夫贿之与赃，一物而两名者，利与害故也。窃人之美谓之徼，其始取之也，唯恐其不多也。及其败露也，唯恐其多矣。夫誉与毁，一事而两名者，名与实故也。凡言朝者，萃名之地也；市者，聚利之地也。能不以争处乎其间，虽一日九迁，一货十倍，何害生实丧之有耶？是知争也者取利之端也，让也者趋名之本也。利至则害生，名兴则实丧。利至名兴，而无害生实丧之患，唯有德者能之。天依地，地会天，岂相远哉！”', '附录·渔樵对问', '附录·渔樵对问·第42则'),
('ATXT_YQ_43', '渔樵对问', 43, '渔者', '渔者谓樵者曰：“天下将治，则人必尚行也；天下将乱，则人必尚言也。尚行，则笃实之风行焉；尚言，则诡谲之风行焉。天下将治，则人必尚义也；天下将乱，则人必尚利也。尚义，则谦让之风行焉；尚利，则攘夺之风行焉。三王，尚行者也；五霸，尚言者也。尚行者必入于义也，尚言者必入于利也。义利之相去，一何如是之远耶？是知言之于口，不若行之于身，行之于身，不若尽之于心。言之于口，人得而闻之，行之于身，人得而见之，尽之于心，神得而知之。人之聪明犹不可欺，况神之聪明乎？是知无愧于口，不若无愧于身，无愧于身，不若无愧于心。无口过易，无身过难，无身过易，无心过难。既无心过，何难之有？吁！安得无心过之人，与之语心哉！”', '附录·渔樵对问', '附录·渔樵对问·第43则'),
('ATXT_YQ_44', '渔樵对问', 44, '渔者', '渔者谓樵者曰：“子知观天地万物之道乎？”', '附录·渔樵对问', '附录·渔樵对问·第44则'),
('ATXT_YQ_45', '渔樵对问', 45, '樵者', '樵者曰：“未也。愿闻其方。”', '附录·渔樵对问', '附录·渔樵对问·第45则'),
('ATXT_YQ_46', '渔樵对问', 46, '渔者', '渔者曰：“夫所以谓之观物者，非以目观之也。非观之以目，而观之以心也；非观之以心，而观之以理也。天下之物，莫不有理焉，莫不有性焉，莫不有命焉。所以谓之理者，穷之而后可知也；所以谓之性者，尽之而后可知也；所似谓之命者，至之而后可知也。此三知也，天下之真知也，虽圣人无以过之也。而过之者，非所以谓之圣人也。夫鉴之所以能为明者，谓其能不隐万物之形也。虽然鉴之能不隐万物之形，未若水之能一万物之形也。虽然水之能一万物之形，又未若圣人之能一万物情也。圣人之所以能一万物之情者，谓其圣人之能反观也。所以谓之反观者，不以我观物也。不以我观物者，以物观物之谓也。既能以物观物，又安有我于其间哉？是知我亦人也，人亦我也，我与人皆物也。此所以能用天下之目为己之目，其目无所不观矣。用天下之耳为己之耳，其耳无所不听矣。用天下之口为己之口，其口无所不言矣。用天下之心为己之心，其心无所不谋矣。天下之观，其于见也，不亦广乎？天下之听，其于闻也，不亦远乎？天下之言，其于论也，不亦高乎？天下之谋，其于乐也，不亦大乎？夫其见至广，其闻至远，其论至高，其乐至大，能为至广、至远、至高、至大之事，而中无一为焉，岂不谓至神至圣者乎？非唯吾谓之至神至圣者乎，而天下谓之至神至圣者乎。非唯一时之天下谓之至神至圣者乎，而千万世之天下谓之至神圣者乎。过此以往，未之或知也已。”', '附录·渔樵对问', '附录·渔樵对问·第46则'),
('ATXT_YQ_47', '渔樵对问', 47, '樵者', '樵者问渔者曰：“子以何道而得鱼？”', '附录·渔樵对问', '附录·渔樵对问·第47则'),
('ATXT_YQ_48', '渔樵对问', 48, '答', '曰：“吾以六物具而得鱼。”', '附录·渔樵对问', '附录·渔樵对问·第48则'),
('ATXT_YQ_49', '渔樵对问', 49, '答', '曰：“六物具也，岂由天乎？”', '附录·渔樵对问', '附录·渔樵对问·第49则'),
('ATXT_YQ_50', '渔樵对问', 50, '答', '曰：“具六物而得鱼者，人也。具六物而所以得鱼者，非人也。”', '附录·渔樵对问', '附录·渔樵对问·第50则'),
('ATXT_YQ_51', '渔樵对问', 51, '樵者', '樵者未达，请问其方。', '附录·渔樵对问', '附录·渔樵对问·第51则'),
('ATXT_YQ_52', '渔樵对问', 52, '渔者', '渔者曰：“六物者，竿也，纶也，浮也，沉也，钩也，饵也。一不具，则鱼不可得。然而六物具而不得鱼者，非人也。六物具而不得鱼者有焉，未有六物不具而得鱼者也。是知具六物者，人也。得鱼与不得鱼，天也。六物不具而不得鱼者，非天也，人也。”', '附录·渔樵对问', '附录·渔樵对问·第52则'),
('ATXT_YQ_53', '渔樵对问', 53, '樵者', '樵者曰：“人有祷鬼神而求福者，福可祷而求耶？求之而可得耶？敢问其所以。”', '附录·渔樵对问', '附录·渔樵对问·第53则'),
('ATXT_YQ_54', '渔樵对问', 54, '答', '曰：“语善恶者，人也；福祸者，天也。天道福善而祸淫，鬼神岂能违天乎？自作之咎，固难逃已。天降之灾，禳之奚益？修德积善，君子常分。安有余事于其间哉！”', '附录·渔樵对问', '附录·渔樵对问·第54则'),
('ATXT_YQ_55', '渔樵对问', 55, '樵者', '樵者曰：“有为善而遇祸，有为福而获福者，何也？”', '附录·渔樵对问', '附录·渔樵对问·第55则'),
('ATXT_YQ_56', '渔樵对问', 56, '渔者', '渔者曰：“有幸与不幸也。幸不幸，命也；当不当，分也。一命一分，人其逃乎？”', '附录·渔樵对问', '附录·渔樵对问·第56则'),
('ATXT_YQ_57', '渔樵对问', 57, '答', '曰：“何谓分？何谓命？”', '附录·渔樵对问', '附录·渔樵对问·第57则'),
('ATXT_YQ_58', '渔樵对问', 58, '答', '曰：“小人之遇福，非分也，有命也；当祸，分也，非命也。君子之遇祸，非分也，有命也；当福，分也，非命也。”', '附录·渔樵对问', '附录·渔樵对问·第58则'),
('ATXT_YQ_59', '渔樵对问', 59, '渔者', '渔者谓樵者曰：“人之所谓亲，莫如父子也；人之所渭疏，莫如路人也。利害在心，则父子过路人远矣。父子之道，天性也。利害犹或夺之，况非天性者乎？夫利害之移人，如是之深也，可不慎乎？路人之相逢则过之，固无相害之心焉，无利害在前故也。有利害在前，则路人与父子，又奚择焉？路人之能相交以义，又何况父子之亲乎？夫义者，让之本也；利者，争之端也。让则有仁，争则有害，仁与害，何相去之远也！尧、舜亦人也。桀、纣亦人也。人与人同而仁与害异尔。仁因义而起，害因利而生。利不以义，则臣弑其君者有焉，子弑其父者有焉。岂若路人之相逢，一目而交袂于中逵者哉！”', '附录·渔樵对问', '附录·渔樵对问·第59则'),
('ATXT_YQ_60', '渔樵对问', 60, '樵者', '樵者谓渔者曰：“吾尝负薪矣，举百斤而无伤吾之身，加十斤则遂伤吾之身，敢问何故？”', '附录·渔樵对问', '附录·渔樵对问·第60则'),
('ATXT_YQ_61', '渔樵对问', 61, '渔者', '渔者曰：“樵则吾不知之矣。以吾之事观之，则易地皆然。吾尝钓而得大鱼，与吾交战。欲弃之，则不能舍，欲取之，则未能胜。终日而后获，几有没溺之患矣。非直有身伤之患耶？鱼与薪则异也，其贪而为伤则一也。百斤，力分之内者也；十斤，力分之外者也。力分之外，虽一毫犹且为害，而况十斤乎？吾之贪鱼亦何以异子之贪薪乎？”', '附录·渔樵对问', '附录·渔樵对问·第61则'),
('ATXT_YQ_62', '渔樵对问', 62, '樵者', '樵者叹曰：“吾而今而后，知量力而动者智矣哉！”', '附录·渔樵对问', '附录·渔樵对问·第62则'),
('ATXT_YQ_63', '渔樵对问', 63, '樵者', '樵者谓渔者曰：“子可谓知《易》之道矣。吾敢问：《易》有太极，太极何物也？”', '附录·渔樵对问', '附录·渔樵对问·第63则'),
('ATXT_YQ_64', '渔樵对问', 64, '答', '曰：“无为之本也。”', '附录·渔樵对问', '附录·渔樵对问·第64则'),
('ATXT_YQ_65', '渔樵对问', 65, '答', '曰：“太极生两仪，两仪，天地之谓乎？”', '附录·渔樵对问', '附录·渔樵对问·第65则'),
('ATXT_YQ_66', '渔樵对问', 66, '答', '曰：“两仪，天地之祖也，非止为天地而已也。太极分而为二，先得一为一，后得一为二。一二谓两仪。”', '附录·渔樵对问', '附录·渔樵对问·第66则'),
('ATXT_YQ_67', '渔樵对问', 67, '答', '曰：“两仪生四象，四象何物也？”', '附录·渔樵对问', '附录·渔樵对问·第67则'),
('ATXT_YQ_68', '渔樵对问', 68, '答', '曰：“大象谓阴阳刚柔。有阴阳然后可以生天，有刚柔然后可以生地。立功之本，于斯为极。”', '附录·渔樵对问', '附录·渔樵对问·第68则'),
('ATXT_YQ_69', '渔樵对问', 69, '答', '曰：“四象生八卦，八卦何谓也？”', '附录·渔樵对问', '附录·渔樵对问·第69则'),
('ATXT_YQ_70', '渔樵对问', 70, '答', '曰：“谓乾、坤、离、坎、兑、艮、震、巽之谓也。迭相盛衰终始于其间矣。因而重之，则六十四卦由是而生也，而《易》之道始备矣。”', '附录·渔樵对问', '附录·渔樵对问·第70则'),
('ATXT_YQ_71', '渔樵对问', 71, '樵者', '樵者问渔者曰：“复何以见天地之心乎？”', '附录·渔樵对问', '附录·渔樵对问·第71则'),
('ATXT_YQ_72', '渔樵对问', 72, '答', '曰：“先阳已尽，后阳始生，则天地始生之际。中则当日月始周之际，末则当星辰始终之际。万物死生，寒暑代谢，昼夜迁变，非此无以见之。当天地穷极之所必变，变则通，通则久，故《象》言‘先王以至日闭关，商旅不行，后不省方’，顺天故也。”', '附录·渔樵对问', '附录·渔樵对问·第72则'),
('ATXT_YQ_73', '渔樵对问', 73, '樵者', '樵者谓渔者曰：“无妄，灾也。敢问其故？”', '附录·渔樵对问', '附录·渔樵对问·第73则'),
('ATXT_YQ_74', '渔樵对问', 74, '答', '曰：“妄则欺也，得之必有祸。斯有妄也，顺天而动，有祸及者，非祸也，灾也。犹农有思丰而不勤稼穑者，其荒也，不亦祸乎？农有勤稼穑而复败诸水旱者，其荒也，不亦灾乎？故《象》言‘先王以茂对时育万物’，贵不妄也。”', '附录·渔樵对问', '附录·渔樵对问·第74则'),
('ATXT_YQ_75', '渔樵对问', 75, '樵者', '樵者问曰：“姤，何也？”', '附录·渔樵对问', '附录·渔樵对问·第75则'),
('ATXT_YQ_76', '渔樵对问', 76, '答', '曰：“姤，遇也，柔遇刚也，与夬正反。夫始逼壮，姤始遇壮，阴始遇阳，故称姤焉。观其姤，天地之心亦可见矣。圣人以德化及此，罔有不昌。故《象》言‘施命诰四方’，履霜之慎，其在此也。”', '附录·渔樵对问', '附录·渔樵对问·第76则'),
('ATXT_YQ_77', '渔樵对问', 77, '渔者', '渔者谓樵者曰：“春为阳始，夏为阳极，秋为阴始，冬为阴极。阳始则温，阳极则热；阴始则凉，阴极则寒。温则生物，热则长物，凉则收物，寒则杀物。皆一气别而为四焉。其生万物也亦然。”', '附录·渔樵对问', '附录·渔樵对问·第77则'),
('ATXT_YQ_78', '渔樵对问', 78, '樵者', '樵者问渔者曰：“人之所以能灵于万物者，何以知其然耶？”', '附录·渔樵对问', '附录·渔樵对问·第78则'),
('ATXT_YQ_79', '渔樵对问', 79, '渔者', '渔者对曰：“谓其目能收万物之色，耳能收万物之声，鼻能收万物之气，口能收万物之味。声色气味者，万物之体也。目耳口鼻者，万人之用也。体无定用，惟变是用。用无定体，惟化是体。体用交而人物之道于是乎备矣。然则人亦物也，圣亦人也。有一物之物，有十物之物，有百物之物，有千物之物，有万物之物，有亿物之物，有兆物之物。生一一之物，当兆物之物者，岂非人乎？有一人之人，有十人之人，有百人之人，有千人之人，有万人之人，有亿人之人，有兆人之人。生一一之人，当兆人之人者，岂非圣乎？是知人也者，物之至者也。圣也者，人之至者也。物之至者始得谓之物之物也。人之至者始得谓之人之人也。夫物之物者，至物之谓也。而人之至者，至人之谓也。以一至物而当一至人，则非圣人而何？人谓之不圣，则吾不信也。何哉？谓其能以一心观万心，一身观万身，一物观万物，一世观万世者焉。又谓其能以心代天意，口代天言，手代天工，身代天事者焉。又谓其能以上识天时，下尽地理，中尽物情，通照人事者焉。又谓其能以弥纶天地，出入造化，进退今古，表里人物者焉。噫！圣人者，非世世而效圣焉。吾不得而目见之也。虽然吾不得而目见之，察其心，观其迹，探其体，潜其用，虽亿万千年亦可以理知之也。人或告我曰：‘天地之外，别有天地万物，异乎此天地万物。’则吾不得而知之也。非唯吾不得而知之也，圣人亦不得而知之也。凡言知者，谓其心得而知之也。言言者，谓其口得而言之也。既心尚不得而知之，口又恶得而言之乎？以心不可得知而知之，是谓妄知也。以不可得言而言之，是谓妄言也。吾又安能从妄人而行妄知妄言者乎！”', '附录·渔樵对问', '附录·渔樵对问·第79则'),
('ATXT_YQ_80', '渔樵对问', 80, '渔者', '渔者谓樵者曰：“仲尼有言曰，殷因于夏礼，所捐益可知也，周因于殷礼，所损益可知也。其或继周者，虽百世可知也。夫如是，则何止于百世而已哉！亿千万世，皆可得而知之也。人皆知仲尼之为仲尼，不知仲尼之所以为仲尼。不欲知仲尼之所以为仲尼则已，如其必欲知仲尼之所以为仲尼，则舍天地将奚之焉？人皆知天地之为天地，不知天地之所以为天地。不欲知天地之所以为天地则已，如其必欲知天地之所以为天地，则舍动静将奚之焉？夫一动一静者，天地至妙者欤？夫一动一静之间者，天地人至妙者欤？是知仲尼之所以能尽三才之道者，谓其行无辙迹也。故有言曰：‘予欲无言。’又曰：‘天何言哉！四时行焉，百物生焉。’其此之谓与？”', '附录·渔樵对问', '附录·渔樵对问·第80则'),
('ATXT_YQ_81', '渔樵对问', 81, '渔者', '渔者谓樵者曰：“大哉！权之与变乎，非圣人无以尽之。变然后知天地之消长，权然后知天下之轻重。消长，时也；轻重，事也。时有否泰，事有损益。圣人不知随时否泰之道，奚由知变之所为乎？圣人不知随时损益之道，奚由知权之所为乎？运消长者，变也；处轻重者，权也。是知权之与变，圣人之一道耳。”', '附录·渔樵对问', '附录·渔樵对问·第81则'),
('ATXT_YQ_82', '渔樵对问', 82, '樵者', '樵者问渔者曰：“人谓死而有知，有诸？”', '附录·渔樵对问', '附录·渔樵对问·第82则'),
('ATXT_YQ_83', '渔樵对问', 83, '答', '曰：“有之。”', '附录·渔樵对问', '附录·渔樵对问·第83则'),
('ATXT_YQ_84', '渔樵对问', 84, '答', '曰：“何以知其然？”', '附录·渔樵对问', '附录·渔樵对问·第84则'),
('ATXT_YQ_85', '渔樵对问', 85, '答', '曰：“以人知之。”', '附录·渔樵对问', '附录·渔樵对问·第85则'),
('ATXT_YQ_86', '渔樵对问', 86, '答', '曰：“何者谓之人？”', '附录·渔樵对问', '附录·渔樵对问·第86则'),
('ATXT_YQ_87', '渔樵对问', 87, '答', '曰：“目耳鼻口心胆脾肾之气全，谓之人。心之灵曰神，胆之灵曰魄，脾之灵曰魂，肾之灵曰精。心之神发乎目，则谓之视；肾之精发乎耳，则谓之听；脾之魂发乎鼻，则谓之臭；胆之魄发乎口，则谓之言。八者具备，然后谓之人。夫人也者，天地万物之秀气也。然而亦有不中者，各求其类也。若全得人类，则谓之曰全人之人。夫全类者，天地万物之中气也，谓之曰全德之人也。全德之人者，人之人者也。夫人之人者，仁人之谓也。唯全人，然后能当之。人之生也，谓其气行；人之死也，谓其形返。气行则神魂交，形返则精魄存。神魂行于天，精魄返于地。行于天，则谓之曰阳行；返于地，则谓之曰阴返。阳行则昼见而夜伏者也，阴返则夜见而昼伏者也。是故知日者月之形也，月者日之影也。阳者阴之形也，阴者阳之影也。人者鬼之形也，鬼者人之影也。人谓鬼无形而无知者，吾不信也。”', '附录·渔樵对问', '附录·渔樵对问·第87则'),
('ATXT_YQ_88', '渔樵对问', 88, '樵者', '樵者问渔者曰：“小人可绝乎？”', '附录·渔樵对问', '附录·渔樵对问·第88则'),
('ATXT_YQ_89', '渔樵对问', 89, '答', '曰：“不可。君子禀阳正气而生，小人禀阴邪气而生。无阴则阳不成，无小人则君子亦不成，唯以盛衰乎其间也。阳六分，则阴四分；阴六分，则阳四分。阳阴相半，则各五分矣。由是知君子小人之时有盛衰也。治世则君子六分。君子六分，则小人四分，小人固不能胜君子矣。乱世则反是。君君，臣臣，父父，子子，兄兄，弟弟，夫夫，妇妇，谓各安其分也。君不君，臣不臣，父不父，子不子，兄不兄，弟不弟，夫不夫，妇不妇，谓各失其分也。此则由世治世乱使之然也。君子常行胜言，小人常言胜行。故世治则笃实之士多，世乱则缘饰之士众。笃实鲜不成事，缘饰鲜不败事。成多国兴，败多国亡。家亦由是而兴亡也。夫兴家与兴国之人，与亡国亡家之人，相去一何远哉！”', '附录·渔樵对问', '附录·渔樵对问·第89则'),
('ATXT_YQ_90', '渔樵对问', 90, '樵者', '樵者问渔者曰：“人所谓才者，有利焉，有害焉者，何也？”', '附录·渔樵对问', '附录·渔樵对问·第90则'),
('ATXT_YQ_91', '渔樵对问', 91, '渔者', '渔者曰：“才一也，利害二也。有才之正者，有才之不正者。才之正者，利乎人而及乎身者也；才之不正者，利乎身而害乎人者也。”', '附录·渔樵对问', '附录·渔樵对问·第91则'),
('ATXT_YQ_92', '渔樵对问', 92, '答', '曰：“不正，则安得谓之才？”', '附录·渔樵对问', '附录·渔樵对问·第92则'),
('ATXT_YQ_93', '渔樵对问', 93, '答', '曰：“人所不能而能之，安得不谓之才？圣人所以惜乎才之难者，谓其能成天下之事而归之正者寡也。若不能归之以正，才则才矣，难乎语其仁也。譬犹药疗疾也，毒药亦有时而用也，可一而不可再也，疾愈则速已，不已则杀人矣。平药则常日而用之可也，重疾非所以能治也。能驱重疾而无害人之毒者，古今人所谓良药也。《易》曰：‘大君有命，开国承家，小人勿用。’如是，则小人亦有时而用之。时平治定，用之则否。《诗》云：‘它山之石，可以攻玉。’其小人之才乎？”', '附录·渔樵对问', '附录·渔樵对问·第93则'),
('ATXT_YQ_94', '渔樵对问', 94, '樵者', '樵者谓渔者曰：“国家之兴亡，与夫才之邪正，则固得闻命矣。然则何不择其人而用之？”', '附录·渔樵对问', '附录·渔樵对问·第94则'),
('ATXT_YQ_95', '渔樵对问', 95, '渔者', '渔者曰：“择臣者，君也；择君者，臣也。贤愚各从其类而为。奈何有尧舜之君，必有尧舜之臣；有桀纣之君，而必有桀纣之臣。尧舜之臣，生乎桀纣之世，桀纣之臣，生于尧舜之世，必非其所用也，虽欲为祸为福，其能行乎？夫上之所好，下必好之。其若影响，岂待驱率而然耶？上好义，则下必好义，而不义者远矣；上好利，下必好利，而不利者远矣。好利者众，则天下日削矣；好义者众，则天下日盛矣。日盛则昌，日削则亡。盛之与削，昌之与亡，岂其远乎？在上之所好耳。夫治世何尝无小人，乱世何尝无君子，不用则善恶何由而行也？”', '附录·渔樵对问', '附录·渔樵对问·第95则'),
('ATXT_YQ_96', '渔樵对问', 96, '樵者', '樵者曰：“善人常寡，而不善人常众；治世常少，而乱世常多，何以知其然耶？”', '附录·渔樵对问', '附录·渔樵对问·第96则'),
('ATXT_YQ_97', '渔樵对问', 97, '答', '曰：“观之于物，何物不然？譬诸五谷，耘之而不苗者有矣。蓬莠不耘而犹生，耘之而求其尽也，亦未如之何矣。由是知君子小人之道，有自来矣。君子见善则喜之，见不善则远之；小人见善则疾之，见不善则喜之。善恶各从其类也。君子见善则就之，见不善则违之；小人见善则违之，见不善则就之。君子见义则迁，见利则止；小人见义则止，见利则迁。迁义则利人，迁利则害人。利人与害人，相去一何远耶？家与国一也，其兴也，君子常多而小人常鲜；其亡也，小人常多而君子常鲜。君子多而去之者，小人也；小人多而去之者，君子也。君子好生，小人好杀。好生则世治，好杀则世乱。君子好义，小人好利。治世则好义，乱世则好利，其理一也。”', '附录·渔樵对问', '附录·渔樵对问·第97则'),
('ATXT_YQ_98', '渔樵对问', 98, '渔者', '钓者谈已，樵者曰：“吾闻古有伏羲，今日如睹其面焉。”拜而谢之，及旦而去。', '附录·渔樵对问', '附录·渔樵对问·第98则'),
('ATXT_SY_01', '宋史·邵雍传', 1, '籍贯·早年', '邵雍字尧夫。其先范阳人，父古徙衡漳，又徙共城。雍年三十，游河南，葬其亲伊水上，遂为河南人。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第1段'),
('ATXT_SY_02', '宋史·邵雍传', 2, '励志游学', '雍少时自雄其才，慷慨欲树功名，于书无所不读。始为学，即坚苦刻厉，寒不炉，暑不扇，夜不就席者数年。已而叹曰：“昔人尚友于古，而吾独未及四方。”于是逾河、汾，涉淮、汉，周流齐、鲁、宋、郑之墟，久之，幡然来归，曰：“道在是矣。”遂不复出。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第2段'),
('ATXT_SY_03', '宋史·邵雍传', 3, '受学李之才·先天之旨', '北海李之才摄共城令，闻雍好学，尝造其庐，谓曰：“子亦闻物理性命之学乎？”雍对曰：“幸受教。”乃事之才，受《河图》、《洛书》、宓羲八卦六十四卦图像。之才之传，远有端绪，而雍探赜索隐，妙悟神契，洞彻蕴奥，汪洋浩博，多其所自得者。及其学益老，德益邵，玩心高明，以观夫天地之运化，阴阳之消长，远而古今世变，微而走飞草木之性情，深造曲畅，庶几所谓不惑，而非依仿象类、亿则屡中者。遂衍宓羲先天之旨，著书十余万言行于世，然世之知其道者鲜矣。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第3段'),
('ATXT_SY_04', '宋史·邵雍传', 4, '安乐窝·行窝', '初至洛，蓬荜环堵，不芘风雨，躬樵爨以事父母，虽平居屡空，而怡然有所甚乐，人莫能窥也。及执亲丧，哀毁尽礼。富弼、司马光、吕公著诸贤退居洛中，雅敬雍，恒相从游，为市园宅。雍岁时耕稼，仅给衣食。名其居曰“安乐窝”，因自号安乐先生。旦则焚香燕坐，晡时酌酒三四瓯，微醺即止，常不及醉也，兴至辄哦诗自咏。春秋时出游城中，风雨常不出，出则乘小车，一人挽之，惟意所适。士大夫家识其车音，争相迎候，童孺厮隶皆欢相谓曰：“吾家先生至也。”不复称其姓字。或留信宿乃去。好事者别作屋如雍所居，以候其至，名曰“行窝”。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第4段'),
('ATXT_SY_05', '宋史·邵雍传', 5, '洛中师友·德化', '司马光兄事雍，而二人纯德尤乡里所慕向，父子昆弟每相饬曰：“毋为不善，恐司马端明、邵先生知。”士之道洛者，有不之公府，必之雍。雍德气粹然，望之知其贤，然不事表襮，不设防畛，群居燕笑终日，不为甚异。与人言，乐道其善而隐其恶。有就问学则答之，未尝强以语人。人无贵贱少长，一接以诚，故贤者悦其德，不贤者服其化。一时洛中人才特盛，而忠厚之风闻天下。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第5段'),
('ATXT_SY_06', '宋史·邵雍传', 6, '熙宁新法·宽民', '熙宁行新法，吏牵迫不可为，或投劾去。雍门生故友居州县者，皆贻书访雍，雍曰：“此贤者所当尽力之时，新法固严，能宽一分，则民受一分赐矣。投劾何益耶？”', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第6段'),
('ATXT_SY_07', '宋史·邵雍传', 7, '应诏辞官·赐谥康节', '嘉佑诏求遗逸，留守王拱辰以雍应诏，授将作监主簿，复举逸士，补颍州团练推官，皆固辞乃受命，竟称疾不之官。熙宁十年，卒，年六十七，赠秘书省著作郎。元佑中赐谥康节。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第7段'),
('ATXT_SY_08', '宋史·邵雍传', 8, '内圣外王之学', '雍高明英迈，迥出千古，而坦夷浑厚，不见圭角，是以清而不激，和而不流，人与交久，益尊信之。河南程颢初侍其父识雍，论议终日，退而叹曰：“尧夫，内圣外王之学也。”', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第8段'),
('ATXT_SY_09', '宋史·邵雍传', 9, '前知·玩世之辨', '雍知虑绝人，遇事能前知。程颐尝曰：“其心虚明，自能知之。”当时学者因雍超诣之识，务高雍所为，至谓雍有玩世之意。又因雍之前知，谓雍于凡物声气之所感触，辄以其动而推其变焉。于是摭世事之已然者，皆以雍言先之，雍盖未必然也。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第9段'),
('ATXT_SY_10', '宋史·邵雍传', 10, '临终·著述', '雍疾病，司马光、张载、程颢、程颐晨夕候之。将终，共议丧葬事外庭，雍皆能闻众人所言，召子伯温谓曰：“诸君欲葬我近城地，当从先茔尔。”既葬，颢为铭墓，称雍之道纯一不杂，就其所至，可谓安且成矣。所著书曰《皇极经世》、《观物内外篇》、《渔樵问对》，诗曰《伊川击壤集》。', '附录·宋史·邵雍传', '附录·宋史·邵雍传·第10段'),
('ATXT_BGJ_01', '八卦诀', 1, '乾宫', '乾为天、天泽履、天火同人、天雷无妄、天风姤、天水讼、天山遁、天地否', '附录·八卦诀', '附录·八卦诀·乾宫'),
('ATXT_BGJ_02', '八卦诀', 2, '兑宫', '兑为泽、泽天夬、泽火革、泽雷随、泽风大过、泽水困、泽山咸、泽地萃', '附录·八卦诀', '附录·八卦诀·兑宫'),
